{
  "name": "SkillPath AI",
  "description": "A personalized learning plan generator that breaks topics down into daily actionable steps, tracks progress on a calendar, and allows for AI-assisted plan refinement."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Task {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface DayPlan {
  dayNumber: number;
  title: string;
  description: string; // Step by step details
  tasks: Task[];
}

export interface LearningPlan {
  id: string;
  topic: string;
  durationDays: number;
  dailyTime: string;
  startDate: string; // ISO String
  lastUpdated: string;
  days: DayPlan[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isError?: boolean;
}

export interface PlanGenerationParams {
  topic: string;
  days: number;
  timePerDay: string;
}

import { GoogleGenAI } from "@google/genai";
import { LearningPlan, DayPlan } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are an expert curriculum designer and educational coach. 
Your goal is to break down complex topics into actionable, bite-sized daily learning plans.
The plans must be practical, step-by-step, and tailored to the user's time constraints.
`;

// Helper to extract JSON from markdown code blocks if present
function extractJson(text: string): any {
  try {
    const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/) || text.match(/```\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1]);
    }
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse JSON from model response", text);
    throw new Error("The model generated an invalid format. Please try again.");
  }
}

export async function generateLearningPlan(topic: string, days: number, timePerDay: string): Promise<Omit<LearningPlan, 'id' | 'startDate' | 'lastUpdated'>> {
  const prompt = `
    Create a ${days}-day learning plan for the topic: "${topic}".
    The user can spend ${timePerDay} per day.

    You MUST use Google Search to ensure the curriculum includes the latest tools, versions, and best practices as of 2024/2025.

    Return ONLY a JSON object with the following structure:
    {
      "topic": "${topic}",
      "durationDays": ${days},
      "dailyTime": "${timePerDay}",
      "days": [
        {
          "dayNumber": 1,
          "title": "Short title for the day",
          "description": "Detailed step-by-step instructions for the day. Do not use generic paragraphs. Use bullet points or numbered lists within this string.",
          "tasks": ["Task 1", "Task 2", "Task 3"]
        }
      ]
    }

    Ensure 'tasks' are short, actionable checkboxes.
    Ensure 'description' contains high-quality, step-by-step educational content.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }], 
        // Note: responseMimeType: 'application/json' is NOT allowed with googleSearch
        // We must rely on the prompt to get JSON.
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = extractJson(text);

    // Transform simple string tasks to Task objects
    const formattedDays: DayPlan[] = data.days.map((d: any) => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map((t: string, idx: number) => ({
        id: `task-${d.dayNumber}-${idx}`,
        text: t,
        isCompleted: false
      }))
    }));

    return {
      topic: data.topic,
      durationDays: data.durationDays,
      dailyTime: data.dailyTime,
      days: formattedDays
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

export async function updatePlanWithChat(currentPlan: LearningPlan, userRequest: string): Promise<LearningPlan> {
  // We need to feed the current plan structure and the user's request
  // We will strip the large 'startDate' etc to save tokens, focusing on the content.

  const simplifiedPlan = {
    days: currentPlan.days.map(d => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map(t => t.text) // Send only text, we will reconstruct IDs later or map them back
    }))
  };

  const prompt = `
    The user wants to modify their current learning plan for "${currentPlan.topic}".

    Current Plan Structure (JSON):
    ${JSON.stringify(simplifiedPlan)}

    User Request: "${userRequest}"

    Please update the plan according to the request. Keep the JSON structure exactly the same as the input.
    If the user asks to add days, increase the day count. If they ask to remove, decrease it.

    Return ONLY the valid JSON of the updated "days" array. 
    Example output: 
    {
      "days": [ ... ]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        // We use search here too in case the user asks for "Include new info about X"
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = extractJson(text);

    // Merge logic: We need to preserve 'isCompleted' status for existing tasks if possible,
    // but often a re-write changes tasks significantly. For simplicity in this v1, 
    // we will reset tasks for modified days or try to match by text if robust.
    // Let's assume a plan update might reset progress for affected days to ensure learning integrity.

    const updatedDays: DayPlan[] = data.days.map((d: any) => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map((t: string, idx: number) => ({
        id: `task-${d.dayNumber}-${idx}-${Date.now()}`, // New IDs to avoid conflicts
        text: t,
        isCompleted: false
      }))
    }));

    return {
      ...currentPlan,
      days: updatedDays,
      durationDays: updatedDays.length,
      lastUpdated: new Date().toISOString()
    };

  } catch (error) {
    console.error("Gemini Update Error:", error);
    throw error;
  }
}

import React, { useState } from 'react';
import { Icons } from './Icons';
import { generateLearningPlan } from '../services/geminiService';
import { LearningPlan } from '../types';
import { v4 as uuidv4 } from 'uuid';

interface PlanWizardProps {
  onPlanCreated: (plan: LearningPlan) => void;
  onCancel: () => void;
}

export const PlanWizard: React.FC<PlanWizardProps> = ({ onPlanCreated, onCancel }) => {
  const [topic, setTopic] = useState('');
  const [days, setDays] = useState(7);
  const [timePerDay, setTimePerDay] = useState('30 mins');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setIsLoading(true);
    setError(null);

    try {
      const planData = await generateLearningPlan(topic, days, timePerDay);

      const newPlan: LearningPlan = {
        ...planData,
        id: uuidv4(),
        startDate: new Date().toISOString(),
        lastUpdated: new Date().toISOString(),
      };

      onPlanCreated(newPlan);
    } catch (err: any) {
      setError(err.message || "Failed to generate plan. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-xl shadow-lg p-8 border border-gray-100">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
          <Icons.Sparkles className="text-indigo-600" />
          Create New Learning Plan
        </h2>
        <button onClick={onCancel} className="text-gray-400 hover:text-gray-600">
          <Icons.X size={24} />
        </button>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-lg text-sm">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            What do you want to learn?
          </label>
          <input
            type="text"
            required
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g., Advanced React Patterns, Introduction to Pottery, Python for Data Science..."
            className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Duration (Days)
            </label>
            <input
              type="number"
              min="1"
              max="60"
              value={days}
              onChange={(e) => setDays(parseInt(e.target.value))}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Time per Day
            </label>
            <select
              value={timePerDay}
              onChange={(e) => setTimePerDay(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all bg-white"
            >
              <option value="15 mins">15 mins</option>
              <option value="30 mins">30 mins</option>
              <option value="45 mins">45 mins</option>
              <option value="1 hour">1 hour</option>
              <option value="2 hours">2 hours</option>
              <option value="3+ hours">3+ hours</option>
            </select>
          </div>
        </div>

        <div className="pt-4">
          <button
            type="submit"
            disabled={isLoading}
            className={`w-full flex items-center justify-center gap-2 py-4 rounded-lg text-white font-medium transition-all ${
              isLoading
                ? 'bg-indigo-400 cursor-not-allowed'
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-md hover:shadow-lg'
            }`}
          >
            {isLoading ? (
              <>
                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                Generating Plan with Gemini...
              </>
            ) : (
              <>
                Generate Plan
                <Icons.ChevronRight size={20} />
              </>
            )}
          </button>
          <p className="text-center text-xs text-gray-500 mt-3">
            Powered by Gemini 2.5 Flash with Google Search Grounding for up-to-date content.
          </p>
        </div>
      </form>
    </div>
  );
};

import React from 'react';
import { LearningPlan, DayPlan } from '../types';
import { Icons } from './Icons';

interface PlanCalendarProps {
  plan: LearningPlan;
  selectedDay: DayPlan | null;
  onSelectDay: (day: DayPlan) => void;
}

export const PlanCalendar: React.FC<PlanCalendarProps> = ({ plan, selectedDay, onSelectDay }) => {

  // Calculate date helpers
  const startDate = new Date(plan.startDate);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const getDayDate = (dayIndex: number) => {
    const date = new Date(startDate);
    date.setDate(startDate.getDate() + dayIndex);
    return date;
  };

  const isSameDay = (d1: Date, d2: Date) => {
    return d1.getFullYear() === d2.getFullYear() &&
           d1.getMonth() === d2.getMonth() &&
           d1.getDate() === d2.getDate();
  };

  const getStatusColor = (day: DayPlan, index: number) => {
    const date = getDayDate(index);
    date.setHours(0, 0, 0, 0);

    const allCompleted = day.tasks.length > 0 && day.tasks.every(t => t.isCompleted);
    const isPast = date < today;
    const isToday = isSameDay(date, today);

    if (allCompleted) return 'bg-emerald-100 border-emerald-300 text-emerald-800 hover:bg-emerald-200';
    if (isPast && !allCompleted) return 'bg-red-50 border-red-200 text-red-800 hover:bg-red-100'; // Missed
    if (isToday) return 'bg-indigo-50 border-indigo-300 text-indigo-800 ring-2 ring-indigo-400 ring-offset-1';

    // Future
    return 'bg-white border-gray-200 text-gray-600 hover:border-indigo-200 hover:text-indigo-600';
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-xl font-bold text-gray-800">{plan.topic}</h2>
          <div className="flex items-center gap-4 text-sm text-gray-500 mt-1">
            <span className="flex items-center gap-1"><Icons.Calendar size={14} /> {plan.durationDays} Days</span>
            <span className="flex items-center gap-1"><Icons.Clock size={14} /> {plan.dailyTime}/day</span>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pr-2">
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
          {plan.days.map((day, index) => {
            const date = getDayDate(index);
            const isSelected = selectedDay?.dayNumber === day.dayNumber;
            const statusClass = getStatusColor(day, index);
            const completedCount = day.tasks.filter(t => t.isCompleted).length;
            const totalTasks = day.tasks.length;

            return (
              <button
                key={day.dayNumber}
                onClick={() => onSelectDay(day)}
                className={`
                  relative flex flex-col items-start p-3 rounded-lg border text-left transition-all
                  ${statusClass}
                  ${isSelected ? 'ring-2 ring-indigo-600 ring-offset-2 z-10' : ''}
                `}
              >
                <div className="flex justify-between w-full items-start mb-2">
                  <span className="text-xs font-semibold uppercase opacity-75">
                    Day {day.dayNumber}
                  </span>
                  {completedCount === totalTasks && totalTasks > 0 && (
                    <Icons.CheckCircle size={14} className="text-emerald-600" />
                  )}
                </div>

                <div className="text-xs opacity-60 mb-1">
                  {date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                </div>

                <h3 className="text-sm font-medium leading-tight line-clamp-2 mb-2 w-full">
                  {day.title}
                </h3>

                <div className="mt-auto w-full">
                  <div className="w-full bg-gray-200/50 rounded-full h-1.5 overflow-hidden">
                    <div 
                      className={`h-full rounded-full transition-all duration-500 ${completedCount === totalTasks ? 'bg-emerald-500' : 'bg-indigo-500'}`}
                      style={{ width: `${(completedCount / totalTasks) * 100}%` }}
                    />
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="mt-6 pt-4 border-t border-gray-100 flex gap-4 text-xs text-gray-500 justify-end">
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 bg-emerald-100 border border-emerald-300 rounded"></div> Completed
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 bg-red-50 border border-red-200 rounded"></div> Missed
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 bg-indigo-50 border border-indigo-300 rounded"></div> Today
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { DayPlan, LearningPlan, Task } from '../types';
import { Icons } from './Icons';
import { updatePlanWithChat } from '../services/geminiService';

interface PlanDetailProps {
  day: DayPlan | null;
  plan: LearningPlan;
  isVisible: boolean;
  onClose: () => void;
  onToggleTask: (dayNumber: number, taskId: string) => void;
  onPlanUpdate: (updatedPlan: LearningPlan) => void;
}

export const PlanDetail: React.FC<PlanDetailProps> = ({ 
  day, 
  plan, 
  isVisible, 
  onClose, 
  onToggleTask,
  onPlanUpdate 
}) => {
  const [activeTab, setActiveTab] = useState<'details' | 'chat'>('details');
  const [chatInput, setChatInput] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const [messages, setMessages] = useState<{role: 'user'|'model', text: string}[]>([
    { role: 'model', text: 'I can help you adjust this learning plan. Need to make it shorter, harder, or focus on a specific sub-topic? Just ask!' }
  ]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  // Reset tab when day changes
  useEffect(() => {
      if (day) setActiveTab('details');
  }, [day]);

  if (!isVisible) return null;

  const handleSendMessage = async () => {
    if (!chatInput.trim() || isUpdating) return;

    const userMsg = chatInput;
    setChatInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsUpdating(true);

    try {
      const updatedPlan = await updatePlanWithChat(plan, userMsg);
      onPlanUpdate(updatedPlan);
      setMessages(prev => [...prev, { role: 'model', text: 'Plan updated successfully! You can see the changes in the calendar and details.' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'Sorry, I encountered an error updating the plan. Please try again.' }]);
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <div className={`
      fixed inset-y-0 right-0 w-full sm:w-96 bg-white shadow-2xl transform transition-transform duration-300 ease-in-out z-30 flex flex-col
      ${isVisible ? 'translate-x-0' : 'translate-x-full'}
    `}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-100 bg-white">
        <div className="flex space-x-4">
            <button 
                onClick={() => setActiveTab('details')}
                className={`text-sm font-medium pb-1 border-b-2 transition-colors ${activeTab === 'details' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500'}`}
            >
                Day Details
            </button>
            <button 
                onClick={() => setActiveTab('chat')}
                className={`text-sm font-medium pb-1 border-b-2 transition-colors ${activeTab === 'chat' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500'}`}
            >
                Edit Plan
            </button>
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
          <Icons.X size={20} />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto bg-gray-50">

        {activeTab === 'details' ? (
            day ? (
                <div className="p-6">
                    <div className="flex items-center gap-2 text-indigo-600 font-semibold text-sm uppercase tracking-wide mb-2">
                        Day {day.dayNumber}
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-4">{day.title}</h2>

                    <div className="prose prose-sm prose-indigo text-gray-600 mb-8">
                         {/* Render step-by-step description with line breaks/bullets if necessary */}
                        {day.description.split('\n').map((line, i) => (
                            <p key={i} className="mb-2">{line}</p>
                        ))}
                    </div>

                    <div className="space-y-3">
                        <h3 className="font-semibold text-gray-800 flex items-center gap-2">
                            <Icons.CheckCircle size={18} />
                            Tasks
                        </h3>
                        {day.tasks.map((task) => (
                            <label 
                                key={task.id} 
                                className={`
                                    flex items-start gap-3 p-3 rounded-lg border transition-all cursor-pointer
                                    ${task.isCompleted ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-gray-200 hover:border-indigo-300'}
                                `}
                            >
                                <input 
                                    type="checkbox" 
                                    checked={task.isCompleted}
                                    onChange={() => onToggleTask(day.dayNumber, task.id)}
                                    className="mt-1 h-4 w-4 text-indigo-600 rounded border-gray-300 focus:ring-indigo-500"
                                />
                                <span className={`text-sm ${task.isCompleted ? 'text-emerald-800 line-through opacity-70' : 'text-gray-700'}`}>
                                    {task.text}
                                </span>
                            </label>
                        ))}
                    </div>
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 p-8 text-center">
                    <Icons.Calendar size={48} className="mb-4 opacity-20" />
                    <p>Select a day from the calendar to view details.</p>
                </div>
            )
        ) : (
            <div className="flex flex-col h-full">
                <div className="flex-1 p-4 space-y-4 overflow-y-auto">
                    {messages.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[85%] p-3 rounded-lg text-sm ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-br-none' : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'}`}>
                                {msg.text}
                            </div>
                        </div>
                    ))}
                    {isUpdating && (
                         <div className="flex justify-start">
                            <div className="bg-gray-100 p-3 rounded-lg rounded-bl-none flex items-center gap-2 text-xs text-gray-500">
                                <div className="animate-spin h-3 w-3 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                                Updating plan structure...
                            </div>
                        </div>
                    )}
                    <div ref={messagesEndRef} />
                </div>
                <div className="p-4 bg-white border-t border-gray-100">
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={chatInput}
                            onChange={(e) => setChatInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                            placeholder="e.g. Add more practical exercises..."
                            className="flex-1 px-4 py-2 text-sm border border-gray-300 rounded-full focus:outline-none focus:ring-2 focus:ring-indigo-500"
                            disabled={isUpdating}
                        />
                        <button 
                            onClick={handleSendMessage}
                            disabled={isUpdating || !chatInput.trim()}
                            className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <Icons.Send size={18} />
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PlanWizard } from './components/PlanWizard';
import { PlanCalendar } from './components/PlanCalendar';
import { PlanDetail } from './components/PlanDetail';
import { Icons } from './components/Icons';
import { LearningPlan, DayPlan } from './types';

// Storage key
const STORAGE_KEY = 'skillpath_plans_v1';

const App: React.FC = () => {
  const [plans, setPlans] = useState<LearningPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'create' | 'view'>('view');

  // Selection state within a plan
  const [selectedDay, setSelectedDay] = useState<DayPlan | null>(null);
  const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsedPlans = JSON.parse(saved);
        setPlans(parsedPlans);
        if (parsedPlans.length > 0) {
          setActivePlanId(parsedPlans[0].id);
        } else {
          setViewMode('create');
        }
      } catch (e) {
        console.error("Failed to parse saved plans");
      }
    } else {
        setViewMode('create');
    }
  }, []);

  // Save to local storage whenever plans change
  useEffect(() => {
    if (plans.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(plans));
    }
  }, [plans]);

  // Select today's day automatically when opening a plan
  useEffect(() => {
    if (activePlanId && plans.length > 0) {
      const plan = plans.find(p => p.id === activePlanId);
      if (plan) {
        const today = new Date();
        today.setHours(0,0,0,0);
        const startDate = new Date(plan.startDate);

        // Calculate diff in days
        const diffTime = Math.abs(today.getTime() - startDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // If today is within the plan range, select it
        if (today >= startDate && diffDays < plan.days.length) {
            // Find the day with index matches today relative to start
            const targetDay = plan.days.find(d => d.dayNumber === diffDays + 1);
            if (targetDay) {
                setSelectedDay(targetDay);
            }
        }
      }
    }
  }, [activePlanId, plans]);

  const handleCreatePlan = (newPlan: LearningPlan) => {
    setPlans(prev => [newPlan, ...prev]);
    setActivePlanId(newPlan.id);
    setViewMode('view');
    // Select first day by default for new plan
    setSelectedDay(newPlan.days[0]);
    setIsSidePanelOpen(true);
  };

  const handleDeletePlan = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Are you sure you want to delete this plan?")) {
      const newPlans = plans.filter(p => p.id !== id);
      setPlans(newPlans);
      if (activePlanId === id) {
        setActivePlanId(newPlans.length > 0 ? newPlans[0].id : null);
        if (newPlans.length === 0) setViewMode('create');
      }
    }
  };

  const handleToggleTask = (dayNumber: number, taskId: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return {
            ...day,
            tasks: day.tasks.map(task => 
              task.id === taskId ? { ...task, isCompleted: !task.isCompleted } : task
            )
          };
        })
      };
    }));

    // Update selected day reference to trigger re-renders in side panel
    if (selectedDay && selectedDay.dayNumber === dayNumber) {
        const updatedPlan = plans.find(p => p.id === activePlanId);
        const updatedDay = updatedPlan?.days.find(d => d.dayNumber === dayNumber);
        // We can't synchronously get the updated state here easily without reducer/complex logic,
        // but react state update will trigger re-render of PlanDetail if we pass the plan days correctly.
    }
  };

  // Need to ensure SelectedDay stays in sync with plans state
  const activePlan = plans.find(p => p.id === activePlanId);
  const currentSelectedDay = activePlan?.days.find(d => d.dayNumber === selectedDay?.dayNumber) || null;

  const handleUpdatePlan = (updatedPlan: LearningPlan) => {
      setPlans(prev => prev.map(p => p.id === updatedPlan.id ? updatedPlan : p));
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row h-screen overflow-hidden">

      {/* Sidebar Navigation */}
      <div className="w-full md:w-64 bg-white border-r border-gray-200 flex flex-col h-auto md:h-full z-20">
        <div className="p-6 border-b border-gray-100 flex items-center gap-2">
            <div className="bg-indigo-600 p-1.5 rounded-lg">
                <Icons.BookOpen className="text-white" size={20} />
            </div>
            <h1 className="font-bold text-xl text-gray-800 tracking-tight">SkillPath AI</h1>
        </div>

        <div className="p-4 flex-1 overflow-y-auto">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 px-2">Your Plans</div>

          <div className="space-y-2">
            {plans.map(plan => (
              <div 
                key={plan.id}
                onClick={() => {
                  setActivePlanId(plan.id);
                  setViewMode('view');
                }}
                className={`group flex items-center justify-between p-3 rounded-lg cursor-pointer transition-all ${activePlanId === plan.id && viewMode === 'view' ? 'bg-indigo-50 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <div className="flex items-center gap-3 truncate">
                  <div className={`w-2 h-2 rounded-full ${activePlanId === plan.id ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                  <span className="font-medium text-sm truncate">{plan.topic}</span>
                </div>
                <button 
                  onClick={(e) => handleDeletePlan(plan.id, e)}
                  className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 transition-opacity"
                >
                  <Icons.Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>

          <button
            onClick={() => setViewMode('create')}
            className={`w-full mt-4 flex items-center gap-2 p-3 rounded-lg text-sm font-medium border border-dashed border-gray-300 text-gray-500 hover:border-indigo-400 hover:text-indigo-600 transition-all ${viewMode === 'create' ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : ''}`}
          >
            <Icons.Plus size={16} />
            New Learning Plan
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col h-full relative overflow-hidden">

        {viewMode === 'create' ? (
          <div className="flex-1 overflow-y-auto p-4 md:p-8 flex items-center justify-center">
            <PlanWizard 
                onPlanCreated={handleCreatePlan} 
                onCancel={() => plans.length > 0 ? setViewMode('view') : null}
            />
          </div>
        ) : (
          activePlan && (
            <div className="flex-1 flex flex-col h-full overflow-hidden p-4 md:p-6">
              {/* Toolbar */}
              <div className="flex justify-between items-center mb-4">
                  <h2 className="text-lg font-semibold text-gray-700 hidden md:block">Learning Progress</h2>
                  <div className="flex gap-2">
                    <button 
                        onClick={() => setIsSidePanelOpen(!isSidePanelOpen)}
                        className={`md:hidden p-2 rounded-lg border ${isSidePanelOpen ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600'}`}
                    >
                        <Icons.Layout size={20} />
                    </button>
                  </div>
              </div>

              {/* Calendar Grid */}
              <div className="flex-1 overflow-hidden">
                <PlanCalendar 
                    plan={activePlan} 
                    selectedDay={currentSelectedDay}
                    onSelectDay={(day) => {
                        setSelectedDay(day);
                        setIsSidePanelOpen(true);
                    }}
                />
              </div>

              {/* Side Panel (Overlay on mobile, persistent on large screens if desired, but request implies collapsible/hidden) */}
              <PlanDetail 
                day={currentSelectedDay}
                plan={activePlan}
                isVisible={isSidePanelOpen}
                onClose={() => setIsSidePanelOpen(false)}
                onToggleTask={handleToggleTask}
                onPlanUpdate={handleUpdatePlan}
              />
            </div>
          )
        )}
      </div>
    </div>
  );
};

export default App;

