const SimpleMarkdown: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;

  // Basic split by newline
  const lines = text.split('\n');

  return (
    <div className="text-sm text-gray-600 space-y-2 whitespace-pre-wrap">
      {lines.map((line, i) => {

        // Headers (###)
        if (line.startsWith('### ')) {
            return <h4 key={i} className="font-bold text-gray-800 mt-4 mb-2">{line.replace('### ', '')}</h4>
        }

        // Bold formatting (**text**)
        const renderBold = (str: string) => {
            const parts = str.split(/(\*\*.*?\*\*)/g);
            return parts.map((part, idx) => {
                 if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-semibold text-gray-900">{part.slice(2, -2)}</strong>;
                 }
                 return part;
            });
        };

        // Lists (unordered)
        if (line.trim().startsWith('- ')) {
            return (
              <p key={i}>
                <span className="mr-2"> - </span>
                {renderBold(line.trim().substring(2))}
              </p>
            );
        }

        // Lists (ordered)
        const orderedMatch = line.trim().match(/^(\d+)\.\s/);
        if (orderedMatch) {
            return (
              <p key={i}>
                <span className="mr-2">{orderedMatch[1]}.</span>
                {renderBold(line.trim().substring(orderedMatch[0].length))}
              </p>
            );
        }

        return <p key={i}>{renderBold(line)}</p>;
      })}
    </div>
  );
};

export default SimpleMarkdown;

