            >
                Edit Plan
            </button>
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
          <Icons.X size={20} />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto bg-gray-50">

        {activeTab === 'details' ? (
            day ? (
                <div className="p-6">
                    <div className="flex items-center gap-2 text-indigo-600 font-semibold text-sm uppercase tracking-wide mb-2">
