        <div className="p-6 border-b border-gray-100 flex items-center gap-2">
            <div className="bg-indigo-600 p-1.5 rounded-lg">
                <Icons.BookOpen className="text-white" size={20} />
            </div>
            <h1 className="font-bold text-xl text-gray-800 tracking-tight">SkillPath AI</h1>
        </div>

        <div className="p-4 flex-1 overflow-y-auto">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 px-2">Your Plans</div>

          <div className="space-y-2">
            {plans.map(plan => (
              <div 
                key={plan.id}
                onClick={() => {
                  setActivePlanId(plan.id);
                  setViewMode('view');
                }}
                className={`group flex items-center justify-between p-3 rounded-lg cursor-pointer transition-all ${activePlanId === plan.id && viewMode === 'view' ? 'bg-indigo-50 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}
              >
                <div className="flex items-center gap-3 truncate">
                  <div className={`w-2 h-2 rounded-full ${activePlanId === plan.id ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                  <span className="font-medium text-sm truncate">{plan.topic}</span>
