              {/* Side Panel */}
              <PlanDetail 
                day={currentSelectedDay}
                plan={activePlan}
                isVisible={isSidePanelOpen}
                onClose={() => setIsSidePanelOpen(false)}
                onToggleTask={handleToggleTask}
                onUpdateNotes={handleUpdateNotes}
              />

              {/* Edit Plan Modal */}
              <EditPlanModal 
                plan={activePlan}
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                onPlanUpdate={handleUpdatePlan}
              />
            </div>
          )
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PlanWizard } from './components/PlanWizard';
import { PlanCalendar } from './components/PlanCalendar';
import { PlanDetail } from './components/PlanDetail';
import { EditPlanModal } from './components/EditPlanModal';
import { Icons } from './components/Icons';
import { LearningPlan, DayPlan } from './types';

// Storage key
const STORAGE_KEY = 'skillpath_plans_v1';

// Background Images (Digital Art)
const BG_LANDING = "url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')";
const BG_PLAN = "url('https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=2574&auto=format&fit=crop')";

const App: React.FC = () => {
  const [plans, setPlans] = useState<LearningPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'create' | 'view'>('view');

  // UI State
  const [selectedDay, setSelectedDay] = useState<DayPlan | null>(null);
  const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsedPlans = JSON.parse(saved);
        setPlans(parsedPlans);
        if (parsedPlans.length > 0) {
          setActivePlanId(parsedPlans[0].id);
        } else {
          setViewMode('create');
        }
      } catch (e) {
        console.error("Failed to parse saved plans");
      }
    } else {
        setViewMode('create');
    }
  }, []);

  // Save to local storage whenever plans change
  useEffect(() => {
    if (plans.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(plans));
    }
  }, [plans]);

  // Select today's day automatically when opening a plan
  useEffect(() => {
    if (activePlanId && plans.length > 0) {
      const plan = plans.find(p => p.id === activePlanId);
      if (plan) {
        const today = new Date();
        today.setHours(0,0,0,0);
        const startDate = new Date(plan.startDate);

        // Calculate diff in days
        const diffTime = Math.abs(today.getTime() - startDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // If today is within the plan range, select it
        if (today >= startDate && diffDays < plan.days.length) {
            // Find the day with index matches today relative to start
            const targetDay = plan.days.find(d => d.dayNumber === diffDays + 1);
            if (targetDay) {
                setSelectedDay(targetDay);
            }
        }
      }
    }
  }, [activePlanId, plans]);

  const handleCreatePlan = (newPlan: LearningPlan) => {
    setPlans(prev => [newPlan, ...prev]);
    setActivePlanId(newPlan.id);
    setViewMode('view');
    // Select first day by default for new plan
    setSelectedDay(newPlan.days[0]);
    setIsSidePanelOpen(true);
  };

  const handleDeletePlan = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Are you sure you want to delete this plan?")) {
      const newPlans = plans.filter(p => p.id !== id);
      setPlans(newPlans);
      if (activePlanId === id) {
        setActivePlanId(newPlans.length > 0 ? newPlans[0].id : null);
        if (newPlans.length === 0) setViewMode('create');
      }
    }
  };

  const handleToggleTask = (dayNumber: number, taskId: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return {
            ...day,
            tasks: day.tasks.map(task => 
              task.id === taskId ? { ...task, isCompleted: !task.isCompleted } : task
            )
          };
        })
      };
    }));

    // Update selected day reference to trigger re-renders in side panel
    if (selectedDay && selectedDay.dayNumber === dayNumber) {
        // Force re-render not needed as props will update
    }
  };

  const handleUpdateNotes = (dayNumber: number, notes: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return { ...day, notes };
        })
      };
    }));
  };

  // Need to ensure SelectedDay stays in sync with plans state
  const activePlan = plans.find(p => p.id === activePlanId);
  const currentSelectedDay = activePlan?.days.find(d => d.dayNumber === selectedDay?.dayNumber) || null;

  const handleUpdatePlan = (updatedPlan: LearningPlan) => {
      setPlans(prev => prev.map(p => p.id === updatedPlan.id ? updatedPlan : p));
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row h-screen overflow-hidden font-sans">

      {/* Sidebar Navigation */}
      <div 
        className={`bg-white border-r border-gray-200 flex flex-col h-auto md:h-full z-20 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'md:w-20' : 'md:w-64'} w-full`}
      >
        <div className={`p-4 border-b border-gray-100 flex items-center ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}`}>
            <div className="flex items-center gap-2 overflow-hidden">
                <div className="bg-indigo-600 p-1.5 rounded-lg flex-shrink-0">
                    <Icons.BookOpen className="text-white" size={20} />
                </div>
                <h1 className={`font-bold text-xl text-gray-800 tracking-tight whitespace-nowrap transition-opacity duration-200 ${isSidebarCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
                    SkillPath
                </h1>
            </div>
            <button 
                onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
                className={`text-gray-400 hover:text-indigo-600 p-1 rounded-md hover:bg-gray-100 transition-colors hidden md:block`}
            >
                <Icons.PanelLeft size={18} />
            </button>
        </div>

        <div className="p-3 flex-1 overflow-y-auto">
          {!isSidebarCollapsed && (
             <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 px-2">Your Plans</div>
          )}

          <div className="space-y-2">
            {plans.map(plan => (
              <div 
                key={plan.id}
                onClick={() => {
                  setActivePlanId(plan.id);
                  setViewMode('view');
                }}
                className={`
                    group flex items-center p-2.5 rounded-lg cursor-pointer transition-all
                    ${activePlanId === plan.id && viewMode === 'view' ? 'bg-indigo-50 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}
                    ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}
                `}
                title={isSidebarCollapsed ? plan.topic : ''}
              >
                <div className="flex items-center gap-3 overflow-hidden">
                  <div className={`w-2 h-2 rounded-full flex-shrink-0 ${activePlanId === plan.id ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                  <span className={`font-medium text-sm truncate transition-all duration-200 ${isSidebarCollapsed ? 'w-0 opacity-0 hidden' : 'w-auto opacity-100'}`}>
                    {plan.topic}
                  </span>
                </div>
                {!isSidebarCollapsed && (
                    <button 
                        onClick={(e) => handleDeletePlan(plan.id, e)}
                        className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 transition-opacity p-1"
                    >
                        <Icons.Trash2 size={14} />
                    </button>
                )}
              </div>
            ))}
          </div>

          <button
            onClick={() => setViewMode('create')}
            className={`
                w-full mt-4 flex items-center gap-2 p-3 rounded-lg text-sm font-medium border border-dashed border-gray-300 text-gray-500 hover:border-indigo-400 hover:text-indigo-600 transition-all 
                ${viewMode === 'create' ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : ''}
                ${isSidebarCollapsed ? 'justify-center px-0' : ''}
            `}
            title={isSidebarCollapsed ? "Create New Plan" : ""}
          >
            <Icons.Plus size={isSidebarCollapsed ? 20 : 16} />
            {!isSidebarCollapsed && <span>New Plan</span>}
          </button>
        </div>
      </div>

      {/* Main Content Area with Background */}
      <div 
        className="flex-1 flex flex-col h-full relative overflow-hidden bg-gray-50 transition-all duration-500"
        style={{ 
            backgroundImage: viewMode === 'create' ? BG_LANDING : BG_PLAN,
            backgroundSize: 'cover',
            backgroundPosition: 'center'
        }}
      >
        {/* Overlay for better readability */}
        <div className="absolute inset-0 bg-white/30 backdrop-blur-[2px] z-0 pointer-events-none"></div>

        {viewMode === 'create' ? (
          <div className="flex-1 overflow-y-auto p-4 md:p-8 flex items-center justify-center relative z-10">
            <PlanWizard 
                onPlanCreated={handleCreatePlan} 
                onCancel={() => plans.length > 0 ? setViewMode('view') : null}
            />
          </div>
        ) : (
          activePlan && (
            <div className="flex-1 flex flex-col h-full overflow-hidden p-4 md:p-6 relative z-10">
              {/* Toolbar */}
              <div className="flex justify-between items-center mb-4 bg-white/80 backdrop-blur-md p-3 rounded-xl border border-white/50 shadow-sm">
                  <h2 className="text-lg font-bold text-gray-800 hidden md:block px-2">Learning Progress</h2>
                  <div className="flex gap-3 ml-auto md:ml-0">
                    <button 
                        onClick={() => setIsEditModalOpen(true)}
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-all shadow-sm shadow-indigo-200"
                    >
                        <Icons.Sparkles size={16} />
                        Edit Plan
                    </button>
                    <button 
                        onClick={() => setIsSidePanelOpen(!isSidePanelOpen)}
                        className={`md:hidden p-2 rounded-lg border ${isSidePanelOpen ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600'}`}
                    >
                        <Icons.Layout size={20} />
                    </button>
                  </div>
              </div>

              {/* Calendar Grid - Wrapped in transculent bg handled by component or here */}
              <div className="flex-1 overflow-hidden rounded-xl shadow-lg border border-white/50 bg-white/90 backdrop-blur-sm">
                <PlanCalendar 
                    plan={activePlan} 
                    selectedDay={currentSelectedDay}
                    onSelectDay={(day) => {
                        setSelectedDay(day);
                        setIsSidePanelOpen(true);
                    }}
                />
              </div>

              {/* Side Panel */}
              <PlanDetail 
                day={currentSelectedDay}
                plan={activePlan}
                isVisible={isSidePanelOpen}
                onClose={() => setIsSidePanelOpen(false)}
                onToggleTask={handleToggleTask}
                onUpdateNotes={handleUpdateNotes}
              />

              {/* Edit Plan Modal */}
              <EditPlanModal 
                plan={activePlan}
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                onPlanUpdate={handleUpdatePlan}
              />
            </div>
          )
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './Icons';
import { generateLearningPlan, updatePlanWithChat } from '../services/geminiService';
import { LearningPlan, DayPlan } from '../types';
import { v4 as uuidv4 } from 'uuid';

interface PlanWizardProps {
  onPlanCreated: (plan: LearningPlan) => void;
  onCancel: () => void;
}

export const PlanWizard: React.FC<PlanWizardProps> = ({ onPlanCreated, onCancel }) => {
  // Form State
  const [topic, setTopic] = useState('');
  const [days, setDays] = useState(7);
  const [timePerDay, setTimePerDay] = useState('30 mins');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Review & Refine State
  const [generatedPlan, setGeneratedPlan] = useState<LearningPlan | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [isRefining, setIsRefining] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Scroll to bottom of list when plan updates
  useEffect(() => {
    if (generatedPlan && scrollRef.current) {
        scrollRef.current.scrollTop = 0;
    }
  }, [generatedPlan?.lastUpdated]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setIsLoading(true);
    setError(null);

    try {
      const planData = await generateLearningPlan(topic, days, timePerDay);

      const newPlan: LearningPlan = {
        ...planData,
        id: uuidv4(),
        startDate: new Date().toISOString(),
        lastUpdated: new Date().toISOString(),
      };

      setGeneratedPlan(newPlan);
    } catch (err: any) {
      setError(err.message || "Failed to generate plan. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRefine = async () => {
    if (!refineInput.trim() || !generatedPlan) return;

    setIsRefining(true);
    setError(null);
    const originalPlan = generatedPlan;

    try {
        // Optimistic UI updates or loading states happen here
        const updated = await updatePlanWithChat(generatedPlan, refineInput);
        setGeneratedPlan(updated);
        setRefineInput('');
    } catch (err: any) {
        setError("Failed to update plan. Please try again.");
        setGeneratedPlan(originalPlan);
    } finally {
        setIsRefining(false);
    }
  };

  const handleConfirm = () => {
      if (generatedPlan) {
          onPlanCreated(generatedPlan);
      }
  };

  // --------------------------------------------------------------------------
  // RENDER: PREVIEW MODE
  // --------------------------------------------------------------------------
  if (generatedPlan) {
    return (
        <div className="w-full max-w-4xl bg-white rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh] animate-in fade-in zoom-in-95 duration-300">
            {/* Header */}
            <div className="p-6 border-b border-gray-100 flex justify-between items-start bg-indigo-600 text-white">
                <div>
                    <div className="flex items-center gap-2 mb-1 opacity-90 text-sm font-medium uppercase tracking-wider">
                        <Icons.Sparkles size={14} /> Plan Preview
                    </div>
                    <h2 className="text-2xl font-bold">{generatedPlan.topic}</h2>
                    <div className="flex gap-4 mt-2 text-indigo-100 text-sm">
                        <span className="flex items-center gap-1"><Icons.Calendar size={14} /> {generatedPlan.durationDays} Days</span>
                        <span className="flex items-center gap-1"><Icons.Clock size={14} /> {generatedPlan.dailyTime}/day</span>
                    </div>
                </div>
                <button onClick={() => setGeneratedPlan(null)} className="text-indigo-200 hover:text-white transition-colors bg-indigo-700/50 p-2 rounded-lg">
                    <Icons.X size={20} />
                </button>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                {/* Left: Plan Content List */}
                <div className="flex-1 overflow-y-auto bg-gray-50 p-6" ref={scrollRef}>
                    <h3 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                        <Icons.BookOpen size={18} className="text-indigo-600" />
                        Curriculum Overview
                    </h3>
                    <div className="space-y-4">
                        {generatedPlan.days.map((day) => (
                            <div key={day.dayNumber} className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
                                <div className="flex justify-between items-start mb-2">
                                    <span className="text-xs font-bold text-indigo-600 uppercase tracking-wide">Day {day.dayNumber}</span>
                                </div>
                                <h4 className="font-bold text-gray-800 mb-2">{day.title}</h4>
                                <p className="text-sm text-gray-600 line-clamp-3 mb-3">{day.description}</p>
                                <div className="flex gap-2 flex-wrap">
                                    {day.tasks.slice(0, 2).map((task, i) => (
                                        <span key={i} className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-md border border-gray-200 truncate max-w-[200px]">
                                            {task.text}
                                        </span>
                                    ))}
                                    {day.tasks.length > 2 && (
                                        <span className="text-xs text-gray-400 px-1 py-1">+{day.tasks.length - 2} more</span>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Right: Actions & Refine */}
                <div className="w-full md:w-80 bg-white border-l border-gray-200 flex flex-col z-10 shadow-lg">
                    <div className="p-4 border-b border-gray-100 bg-gray-50/50">
                        <h3 className="font-semibold text-gray-800 mb-1">Not quite right?</h3>
                        <p className="text-xs text-gray-500">Ask AI to adjust the duration, difficulty, or content.</p>
                    </div>

                    <div className="p-4 flex-1 flex flex-col gap-2">
                         <textarea
                            value={refineInput}
                            onChange={(e) => setRefineInput(e.target.value)}
                            placeholder="e.g. 'Make it 5 days instead', 'Focus more on practical examples', 'Remove the advanced topics'"
                            className="w-full flex-1 p-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm resize-none"
                            disabled={isRefining}
                        />
                        <button
                            onClick={handleRefine}
                            disabled={!refineInput.trim() || isRefining}
                            className="flex items-center justify-center gap-2 py-2 bg-indigo-100 text-indigo-700 rounded-lg hover:bg-indigo-200 font-medium text-sm transition-colors disabled:opacity-50"
                        >
                            {isRefining ? <div className="animate-spin h-4 w-4 border-2 border-indigo-700 border-t-transparent rounded-full"></div> : <Icons.Sparkles size={16} />}
                            Update Plan
                        </button>
                    </div>

                    <div className="p-4 border-t border-gray-100 bg-gray-50">
                        <button
                            onClick={handleConfirm}
                            className="w-full py-3 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 font-bold shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2"
                        >
                            <Icons.CheckCircle size={18} />
                            Confirm & Start Learning
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
  }

  // --------------------------------------------------------------------------
  // RENDER: WIZARD FORM
  // --------------------------------------------------------------------------
  return (
    <div className="max-w-2xl w-full mx-auto bg-white rounded-xl shadow-lg p-8 border border-gray-100 animate-in slide-in-from-bottom-4 fade-in duration-500">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
          <Icons.Sparkles className="text-indigo-600" />
          Create New Learning Plan
        </h2>
        <button onClick={onCancel} className="text-gray-400 hover:text-gray-600">
          <Icons.X size={24} />
        </button>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-lg text-sm border border-red-100">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            What do you want to learn?
          </label>
          <input
            type="text"
            required
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g., Advanced React Patterns, Introduction to Pottery, Python for Data Science..."
            className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Duration (Days)
            </label>
            <input
              type="number"
              min="1"
              max="60"
              value={days}
              onChange={(e) => setDays(parseInt(e.target.value))}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Time per Day
            </label>
            <select
              value={timePerDay}
              onChange={(e) => setTimePerDay(e.target.value)}
              className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all bg-white"
            >
              <option value="15 mins">15 mins</option>
              <option value="30 mins">30 mins</option>
              <option value="45 mins">45 mins</option>
              <option value="1 hour">1 hour</option>
              <option value="2 hours">2 hours</option>
              <option value="3+ hours">3+ hours</option>
            </select>
          </div>
        </div>

        <div className="pt-4">
          <button
            type="submit"
            disabled={isLoading}
            className={`w-full flex items-center justify-center gap-2 py-4 rounded-lg text-white font-medium transition-all ${
              isLoading
                ? 'bg-indigo-400 cursor-not-allowed'
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-md hover:shadow-lg'
            }`}
          >
            {isLoading ? (
              <>
                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                Generating Plan with Gemini...
              </>
            ) : (
              <>
                Generate Plan
                <Icons.ChevronRight size={20} />
              </>
            )}
          </button>
          <p className="text-center text-xs text-gray-500 mt-3">
            Powered by Gemini 2.5 Flash with Google Search Grounding for up-to-date content.
          </p>
        </div>
      </form>
    </div>
  );
};

export interface Task {
  id: string;
  text: string;
  isCompleted: boolean;
}

export interface Session {
  start: number;
  end: number | null;
}

export interface DayPlan {
  dayNumber: number;
  title: string;
  description: string; // Step by step details
  tasks: Task[];
  notes?: string;
  sessions?: Session[];
}

export interface LearningPlan {
  id: string;
  topic: string;
  durationDays: number;
  dailyTime: string;
  startDate: string; // ISO String
  lastUpdated: string;
  days: DayPlan[];
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isError?: boolean;
}

export interface PlanGenerationParams {
  topic: string;
  days: number;
  timePerDay: string;
}

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PlanWizard } from './components/PlanWizard';
import { PlanCalendar } from './components/PlanCalendar';
import { PlanDetail } from './components/PlanDetail';
import { EditPlanModal } from './components/EditPlanModal';
import { Icons } from './components/Icons';
import { LearningPlan, DayPlan } from './types';

// Storage key
const STORAGE_KEY = 'skillpath_plans_v1';

// Background Images (Digital Art)
const BG_LANDING = "url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')";
const BG_PLAN = "url('https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=2574&auto=format&fit=crop')";

const App: React.FC = () => {
  const [plans, setPlans] = useState<LearningPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'create' | 'view'>('view');

  // UI State
  const [selectedDay, setSelectedDay] = useState<DayPlan | null>(null);
  const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsedPlans = JSON.parse(saved);
        setPlans(parsedPlans);
        if (parsedPlans.length > 0) {
          setActivePlanId(parsedPlans[0].id);
        } else {
          setViewMode('create');
        }
      } catch (e) {
        console.error("Failed to parse saved plans");
      }
    } else {
        setViewMode('create');
    }
  }, []);

  // Save to local storage whenever plans change
  useEffect(() => {
    if (plans.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(plans));
    }
  }, [plans]);

  // Select today's day automatically when opening a plan
  useEffect(() => {
    if (activePlanId && plans.length > 0) {
      const plan = plans.find(p => p.id === activePlanId);
      if (plan) {
        const today = new Date();
        today.setHours(0,0,0,0);
        const startDate = new Date(plan.startDate);

        // Calculate diff in days
        const diffTime = Math.abs(today.getTime() - startDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // If today is within the plan range, select it
        if (today >= startDate && diffDays < plan.days.length) {
            // Find the day with index matches today relative to start
            const targetDay = plan.days.find(d => d.dayNumber === diffDays + 1);
            if (targetDay) {
                setSelectedDay(targetDay);
            }
        }
      }
    }
  }, [activePlanId, plans]);

  const handleCreatePlan = (newPlan: LearningPlan) => {
    setPlans(prev => [newPlan, ...prev]);
    setActivePlanId(newPlan.id);
    setViewMode('view');
    // Select first day by default for new plan
    setSelectedDay(newPlan.days[0]);
    setIsSidePanelOpen(true);
  };

  const handleDeletePlan = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Are you sure you want to delete this plan?")) {
      const newPlans = plans.filter(p => p.id !== id);
      setPlans(newPlans);
      if (activePlanId === id) {
        setActivePlanId(newPlans.length > 0 ? newPlans[0].id : null);
        if (newPlans.length === 0) setViewMode('create');
      }
    }
  };

  const handleToggleTask = (dayNumber: number, taskId: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return {
            ...day,
            tasks: day.tasks.map(task => 
              task.id === taskId ? { ...task, isCompleted: !task.isCompleted } : task
            )
          };
        })
      };
    }));

    // Update selected day reference to trigger re-renders in side panel
    if (selectedDay && selectedDay.dayNumber === dayNumber) {
        // Force re-render not needed as props will update
    }
  };

  const handleUpdateNotes = (dayNumber: number, notes: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return { ...day, notes };
        })
      };
    }));
  };

  const handleSessionToggle = (dayNumber: number) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;

          const sessions = day.sessions || [];
          const lastSession = sessions.length > 0 ? sessions[sessions.length - 1] : null;
          const isRunning = lastSession && lastSession.end === null;

          let newSessions;
          if (isRunning) {
            // Stop session
            newSessions = [...sessions];
            newSessions[sessions.length - 1] = { ...lastSession, end: Date.now() };
          } else {
            // Start session
            newSessions = [...sessions, { start: Date.now(), end: null }];
          }

          return { ...day, sessions: newSessions };
        })
      };
    }));
  };

  // Need to ensure SelectedDay stays in sync with plans state
  const activePlan = plans.find(p => p.id === activePlanId);
  const currentSelectedDay = activePlan?.days.find(d => d.dayNumber === selectedDay?.dayNumber) || null;

  const handleUpdatePlan = (updatedPlan: LearningPlan) => {
      setPlans(prev => prev.map(p => p.id === updatedPlan.id ? updatedPlan : p));
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row h-screen overflow-hidden font-sans">

      {/* Sidebar Navigation */}
      <div 
        className={`bg-white border-r border-gray-200 flex flex-col h-auto md:h-full z-20 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'md:w-20' : 'md:w-64'} w-full`}
      >
        <div className={`p-4 border-b border-gray-100 flex items-center ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}`}>
            <div className="flex items-center gap-2 overflow-hidden">
                <div className="bg-indigo-600 p-1.5 rounded-lg flex-shrink-0">
                    <Icons.BookOpen className="text-white" size={20} />
                </div>
                <h1 className={`font-bold text-xl text-gray-800 tracking-tight whitespace-nowrap transition-opacity duration-200 ${isSidebarCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
                    SkillPath
                </h1>
            </div>
            <button 
                onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
                className={`text-gray-400 hover:text-indigo-600 p-1 rounded-md hover:bg-gray-100 transition-colors hidden md:block`}
            >
                <Icons.PanelLeft size={18} />
            </button>
        </div>

        <div className="p-3 flex-1 overflow-y-auto">
          {!isSidebarCollapsed && (
             <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 px-2">Your Plans</div>
          )}

          <div className="space-y-2">
            {plans.map(plan => (
              <div 
                key={plan.id}
                onClick={() => {
                  setActivePlanId(plan.id);
                  setViewMode('view');
                }}
                className={`
                    group flex items-center p-2.5 rounded-lg cursor-pointer transition-all
                    ${activePlanId === plan.id && viewMode === 'view' ? 'bg-indigo-50 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}
                    ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}
                `}
                title={isSidebarCollapsed ? plan.topic : ''}
              >
                <div className="flex items-center gap-3 overflow-hidden">
                  <div className={`w-2 h-2 rounded-full flex-shrink-0 ${activePlanId === plan.id ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                  <span className={`font-medium text-sm truncate transition-all duration-200 ${isSidebarCollapsed ? 'w-0 opacity-0 hidden' : 'w-auto opacity-100'}`}>
                    {plan.topic}
                  </span>
                </div>
                {!isSidebarCollapsed && (
                    <button 
                        onClick={(e) => handleDeletePlan(plan.id, e)}
                        className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 transition-opacity p-1"
                    >
                        <Icons.Trash2 size={14} />
                    </button>
                )}
              </div>
            ))}
          </div>

          <button
            onClick={() => setViewMode('create')}
            className={`
                w-full mt-4 flex items-center gap-2 p-3 rounded-lg text-sm font-medium border border-dashed border-gray-300 text-gray-500 hover:border-indigo-400 hover:text-indigo-600 transition-all 
                ${viewMode === 'create' ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : ''}
                ${isSidebarCollapsed ? 'justify-center px-0' : ''}
            `}
            title={isSidebarCollapsed ? "Create New Plan" : ""}
          >
            <Icons.Plus size={isSidebarCollapsed ? 20 : 16} />
            {!isSidebarCollapsed && <span>New Plan</span>}
          </button>
        </div>
      </div>

      {/* Main Content Area with Background */}
      <div 
        className="flex-1 flex flex-col h-full relative overflow-hidden bg-gray-50 transition-all duration-500"
        style={{ 
            backgroundImage: viewMode === 'create' ? BG_LANDING : BG_PLAN,
            backgroundSize: 'cover',
            backgroundPosition: 'center'
        }}
      >
        {/* Overlay for better readability */}
        <div className="absolute inset-0 bg-white/30 backdrop-blur-[2px] z-0 pointer-events-none"></div>

        {viewMode === 'create' ? (
          <div className="flex-1 overflow-y-auto p-4 md:p-8 flex items-center justify-center relative z-10">
            <PlanWizard 
                onPlanCreated={handleCreatePlan} 
                onCancel={() => plans.length > 0 ? setViewMode('view') : null}
            />
          </div>
        ) : (
          activePlan && (
            <div className="flex-1 flex flex-col h-full overflow-hidden p-4 md:p-6 relative z-10">
              {/* Toolbar */}
              <div className="flex justify-between items-center mb-4 bg-white/80 backdrop-blur-md p-3 rounded-xl border border-white/50 shadow-sm">
                  <h2 className="text-lg font-bold text-gray-800 hidden md:block px-2">Learning Progress</h2>
                  <div className="flex gap-3 ml-auto md:ml-0">
                    <button 
                        onClick={() => setIsEditModalOpen(true)}
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-all shadow-sm shadow-indigo-200"
                    >
                        <Icons.Sparkles size={16} />
                        Edit Plan
                    </button>
                    <button 
                        onClick={() => setIsSidePanelOpen(!isSidePanelOpen)}
                        className={`md:hidden p-2 rounded-lg border ${isSidePanelOpen ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600'}`}
                    >
                        <Icons.Layout size={20} />
                    </button>
                  </div>
              </div>

              {/* Calendar Grid - Wrapped in transculent bg handled by component or here */}
              <div className="flex-1 overflow-hidden rounded-xl shadow-lg border border-white/50 bg-white/90 backdrop-blur-sm">
                <PlanCalendar 
                    plan={activePlan} 
                    selectedDay={currentSelectedDay}
                    onSelectDay={(day) => {
                        setSelectedDay(day);
                        setIsSidePanelOpen(true);
                    }}
                />
              </div>

              {/* Side Panel */}
              <PlanDetail 
                day={currentSelectedDay}
                plan={activePlan}
                isVisible={isSidePanelOpen}
                onClose={() => setIsSidePanelOpen(false)}
                onToggleTask={handleToggleTask}
                onUpdateNotes={handleUpdateNotes}
                onToggleSession={handleSessionToggle}
              />

              {/* Edit Plan Modal */}
              <EditPlanModal 
                plan={activePlan}
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                onPlanUpdate={handleUpdatePlan}
              />
            </div>
          )
        )}
      </div>
    </div>
  );
};

