import React, { useState, useEffect } from 'react';
import { DayPlan, LearningPlan } from '../types';
import { Icons } from './Icons';

interface PlanDetailProps {
  day: DayPlan | null;
  plan: LearningPlan;
  isVisible: boolean;
  onClose: () => void;
  onToggleTask: (dayNumber: number, taskId: string) => void;
  onUpdateNotes: (dayNumber: number, notes: string) => void;
  onToggleSession: (dayNumber: number) => void;
}

const SimpleMarkdown: React.FC<{ text: string }> = ({ text }) => {
  if (!text) return null;

  const lines = text.split('\n');

  return (
    <div className="text-sm text-gray-600 space-y-1.5 leading-relaxed">
      {lines.map((line, i) => {
        const trimmed = line.trim();

        // Headers (###)
        if (trimmed.startsWith('### ')) {
            return <h4 key={i} className="font-bold text-gray-800 mt-4 mb-2 text-base">{trimmed.replace('### ', '')}</h4>
        }
        if (trimmed.startsWith('## ')) {
            return <h3 key={i} className="font-bold text-gray-800 mt-5 mb-2 text-lg">{trimmed.replace('## ', '')}</h3>
        }

        // Bold formatting (**text**)
        const renderBold = (str: string) => {
            const parts = str.split(/(\*\*.*?\*\*)/g);
            return parts.map((part, idx) => {
                 if (part.startsWith('**') && part.endsWith('**')) {
                     return <strong key={idx} className="font-semibold text-gray-900">{part.slice(2, -2)}</strong>;
                 }
                 return <span key={idx}>{part}</span>;
            });
        };

        // Lists
        if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
            return (
                <div key={i} className="flex gap-2 pl-2 items-start">
                    <span className="text-indigo-500 font-bold mt-1.5 text-[6px]">•</span>
                    <span>{renderBold(trimmed.substring(2))}</span>
                </div>
            );
        }

        // Numbered lists
        if (/^\d+\.\s/.test(trimmed)) {
            const match = trimmed.match(/^(\d+)\.\s(.*)/);
            if (match) {
                 return (
                    <div key={i} className="flex gap-2 pl-2 items-start">
                        <span className="text-indigo-500 font-semibold min-w-[16px]">{match[1]}.</span>
                        <span>{renderBold(match[2])}</span>
                    </div>
                );
            }
        }

        // Empty lines
        if (!trimmed) return <div key={i} className="h-2"></div>;

        // Paragraphs
        return <p key={i} className="mb-1">{renderBold(line)}</p>;
      })}
    </div>
  );
};

export const PlanDetail: React.FC<PlanDetailProps> = ({ 
  day, 
  plan, 
  isVisible, 
  onClose, 
  onToggleTask,
  onUpdateNotes,
  onToggleSession
}) => {
  const [notesInput, setNotesInput] = useState('');
  const [elapsed, setElapsed] = useState(0);

  // Reset notes when day changes
  useEffect(() => {
      if (day) {
          setNotesInput(day.notes || '');
      }
  }, [day]);

  // Timer logic
  useEffect(() => {
    let interval: any;
    if (day && isVisible) {
        // Calculate total previously elapsed time
        const calculateTotal = () => {
             const sessions = day.sessions || [];
             let total = 0;
             let running = false;
             const now = Date.now();

             sessions.forEach(s => {
                 if (s.end) {
                     total += s.end - s.start;
                 } else {
                     total += now - s.start;
                     running = true;
                 }
             });
             return { total, running };
        };

        // Update immediately
        setElapsed(calculateTotal().total);

        // Update every second if running
        interval = setInterval(() => {
            const { total, running } = calculateTotal();
            setElapsed(total);
            if (!running) {
                // If not running, we don't strictly need to clear interval, 
                // but checking less frequently is fine. However, React updates are cheap here.
            }
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [day, isVisible]);

  if (!isVisible) return null;

  const handleNotesBlur = () => {
      if (day && notesInput !== day.notes) {
          onUpdateNotes(day.dayNumber, notesInput);
      }
  };

  const isSessionRunning = day?.sessions && day.sessions.length > 0 && day.sessions[day.sessions.length - 1].end === null;

  const formatTime = (ms: number) => {
      const seconds = Math.floor((ms / 1000) % 60);
      const minutes = Math.floor((ms / (1000 * 60)) % 60);
      const hours = Math.floor((ms / (1000 * 60 * 60)));
      return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className={`
      fixed inset-y-0 right-0 w-full sm:w-96 bg-white shadow-2xl transform transition-transform duration-300 ease-in-out z-30 flex flex-col
      ${isVisible ? 'translate-x-0' : 'translate-x-full'}
    `}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-100 bg-white">
        <h2 className="text-lg font-bold text-gray-800">Daily Plan Details</h2>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
          <Icons.X size={20} />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto bg-gray-50">

        {day ? (
            <div className="p-6">
                <div className="flex items-center justify-between mb-2">
                     <div className="flex items-center gap-2 text-indigo-600 font-semibold text-sm uppercase tracking-wide">
                        Day {day.dayNumber}
                    </div>
                </div>

                <h2 className="text-2xl font-bold text-gray-900 mb-6">{day.title}</h2>

                {/* Timer Section */}
                <div className="bg-indigo-900 rounded-xl p-5 text-white mb-8 shadow-lg relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-10">
                        <Icons.Timer size={80} />
                    </div>
                    <div className="relative z-10">
                        <div className="text-indigo-200 text-xs font-semibold uppercase tracking-wider mb-1">Time Spent Today</div>
                        <div className="text-4xl font-mono font-bold mb-4 tracking-wider">
                            {formatTime(elapsed)}
                        </div>
                        <button 
                            onClick={() => onToggleSession(day.dayNumber)}
                            className={`
                                w-full flex items-center justify-center gap-2 py-2.5 rounded-lg font-bold text-sm transition-all
                                ${isSessionRunning 
                                    ? 'bg-red-500 hover:bg-red-600 text-white shadow-md' 
                                    : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-md'}
                            `}
                        >
                            {isSessionRunning ? (
                                <>
                                    <Icons.Square size={16} fill="currentColor" /> Stop Session
                                </>
                            ) : (
                                <>
                                    <Icons.Play size={16} fill="currentColor" /> Start Learning
                                </>
                            )}
                        </button>
                    </div>
                </div>

                {/* Tasks Section */}
                <div className="space-y-3 mb-8">
                    <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                        <Icons.CheckCircle size={18} className="text-indigo-600" />
                        Tasks Checklist
                    </h3>
                    <div className="bg-gray-50 rounded-xl p-2 border border-gray-100">
                        {day.tasks.map((task) => (
                            <label 
                                key={task.id} 
                                className={`
                                    flex items-start gap-3 p-3 rounded-lg border transition-all cursor-pointer mb-2 last:mb-0
                                    ${task.isCompleted ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-gray-200 hover:border-indigo-300'}
                                `}
                            >
                                <input 
                                    type="checkbox" 
                                    checked={task.isCompleted}
                                    onChange={() => onToggleTask(day.dayNumber, task.id)}
                                    className="mt-1 h-4 w-4 text-indigo-600 rounded border-gray-300 focus:ring-indigo-500"
                                />
                                <span className={`text-sm ${task.isCompleted ? 'text-emerald-800 line-through opacity-70' : 'text-gray-700'}`}>
                                    {task.text}
                                </span>
                            </label>
                        ))}
                    </div>
                </div>

                {/* Description Section */}
                <div className="mb-8">
                        <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                        <Icons.BookOpen size={18} className="text-indigo-600" />
                        Step-by-Step Guide
                    </h3>
                    <div className="prose prose-sm prose-indigo max-w-none bg-white">
                        <SimpleMarkdown text={day.description} />
                    </div>
                </div>

                {/* Notes Section */}
                <div className="mb-8">
                    <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                        <Icons.MessageSquare size={18} className="text-indigo-600" />
                        My Learning Notes
                    </h3>
                    <textarea
                        value={notesInput}
                        onChange={(e) => setNotesInput(e.target.value)}
                        onBlur={handleNotesBlur}
                        placeholder="Write down your key takeaways, code snippets, or ideas here..."
                        className="w-full h-32 p-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm text-gray-700 placeholder-gray-400 resize-y"
                    />
                    <p className="text-xs text-gray-400 mt-1 text-right">Saved automatically on blur</p>
                </div>
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center h-full text-gray-400 p-8 text-center">
                <Icons.Calendar size={48} className="mb-4 opacity-20" />
                <p>Select a day from the calendar to view details.</p>
            </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LearningPlan, DayPlan } from '../types';
import { Icons } from './Icons';

interface PlanCalendarProps {
  plan: LearningPlan;
  selectedDay: DayPlan | null;
  onSelectDay: (day: DayPlan) => void;
}

export const PlanCalendar: React.FC<PlanCalendarProps> = ({ plan, selectedDay, onSelectDay }) => {

  // Calculate date helpers
  const startDate = new Date(plan.startDate);
  // Ensure we work with clean dates
  startDate.setHours(0,0,0,0);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // State for the currently viewed month
  const [viewDate, setViewDate] = useState(() => {
    // Default to showing the month of the selected day, or today, or start date
    if (selectedDay) {
       const d = new Date(startDate);
       d.setDate(d.getDate() + (selectedDay.dayNumber - 1));
       d.setDate(1); // First of month
       return d;
    }
    // Check if today is within plan range
    const endDate = new Date(startDate);
    endDate.setDate(endDate.getDate() + plan.durationDays);

    if (today >= startDate && today <= endDate) {
        const d = new Date(today);
        d.setDate(1);
        return d;
    }

    const d = new Date(startDate);
    d.setDate(1);
    return d;
  });

  // Update view when plan changes or selectedDay changes (optional, but good UX to jump to selection)
  useEffect(() => {
    if (selectedDay) {
        const d = new Date(startDate);
        d.setDate(d.getDate() + (selectedDay.dayNumber - 1));
        const monthStart = new Date(d.getFullYear(), d.getMonth(), 1);

        setViewDate(prev => {
            if (prev.getTime() !== monthStart.getTime()) return monthStart;
            return prev;
        });
    }
  }, [selectedDay, plan.id, plan.startDate]);

  const getDayDate = (dayNumber: number) => {
    const date = new Date(startDate);
    date.setDate(startDate.getDate() + (dayNumber - 1));
    return date;
  };

  const isSameDay = (d1: Date, d2: Date) => {
    return d1.getFullYear() === d2.getFullYear() &&
           d1.getMonth() === d2.getMonth() &&
           d1.getDate() === d2.getDate();
  };

  const getStatusColor = (day: DayPlan, date: Date, isSelected: boolean) => {
    const allCompleted = day.tasks.length > 0 && day.tasks.every(t => t.isCompleted);
    const isPast = date < today;
    const isToday = isSameDay(date, today);

    // If selected, we override the base border color logic in the render, 
    // but the background should still reflect status

    if (allCompleted) return 'bg-emerald-50 text-emerald-900';
    if (isPast && !allCompleted) return 'bg-red-50 text-red-900'; 
    if (isToday) return 'bg-white text-indigo-900'; // Today special handling handled below usually

    // Future / Default
    return 'bg-white text-gray-700';
  };

  const getBorderClass = (day: DayPlan, date: Date, isSelected: boolean) => {
    const allCompleted = day.tasks.length > 0 && day.tasks.every(t => t.isCompleted);
    const isPast = date < today;
    const isToday = isSameDay(date, today);

    if (isSelected) return 'border-2 border-indigo-600 ring-4 ring-indigo-50 shadow-md transform scale-[1.02] z-10';

    if (isToday) return 'border-2 border-indigo-300 ring-2 ring-indigo-50';
    if (allCompleted) return 'border border-emerald-200 hover:border-emerald-400';
    if (isPast) return 'border border-red-200 hover:border-red-300';

    return 'border border-gray-200 hover:border-indigo-300';
  }

  const formatShortDuration = (ms: number) => {
      const mins = Math.floor(ms / (1000 * 60));
      if (mins < 60) return `${mins}m`;
      const hours = Math.floor(mins / 60);
      const remainingMins = mins % 60;
      return `${hours}h ${remainingMins}m`;
  }

  // Pagination Logic
  const nextMonth = () => {
      const next = new Date(viewDate);
      next.setMonth(next.getMonth() + 1);
      setViewDate(next);
  };

  const prevMonth = () => {
      const prev = new Date(viewDate);
      prev.setMonth(prev.getMonth() - 1);
      setViewDate(prev);
  };

  // Filter days for current view
  const currentDays = plan.days.filter(day => {
      const date = getDayDate(day.dayNumber);
      return date.getMonth() === viewDate.getMonth() && date.getFullYear() === viewDate.getFullYear();
  });

  // Calculate plan bounds to disable buttons
  const planEndDate = new Date(startDate);
  planEndDate.setDate(planEndDate.getDate() + plan.durationDays - 1);
  const planEndMonth = new Date(planEndDate.getFullYear(), planEndDate.getMonth(), 1);
  const planStartMonth = new Date(startDate.getFullYear(), startDate.getMonth(), 1);

  const canGoPrev = viewDate > planStartMonth;
  const canGoNext = viewDate < planEndMonth;

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-xl font-bold text-gray-800">{plan.topic}</h2>
          <div className="flex items-center gap-4 text-sm text-gray-500 mt-1">
            <span className="flex items-center gap-1"><Icons.Calendar size={14} /> {plan.durationDays} Days</span>
            <span className="flex items-center gap-1"><Icons.Clock size={14} /> {plan.dailyTime}/day</span>
          </div>
        </div>

        {/* Pagination Controls */}
        <div className="flex items-center gap-4 bg-gray-50 rounded-lg p-1 border border-gray-100">
            <button 
                onClick={prevMonth} 
                disabled={!canGoPrev}
                className={`p-1.5 rounded-md transition-all ${!canGoPrev ? 'text-gray-300 cursor-not-allowed' : 'text-gray-600 hover:bg-white hover:shadow-sm'}`}
            >
                <Icons.ChevronLeft size={20} />
            </button>
            <span className="text-sm font-semibold text-gray-700 min-w-[100px] text-center">
                {viewDate.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}
            </span>
            <button 
                onClick={nextMonth} 
                disabled={!canGoNext}
                className={`p-1.5 rounded-md transition-all ${!canGoNext ? 'text-gray-300 cursor-not-allowed' : 'text-gray-600 hover:bg-white hover:shadow-sm'}`}
            >
                <Icons.ChevronRight size={20} />
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pr-2 pb-2">
        {currentDays.length > 0 ? (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
            {currentDays.map((day) => {
                const date = getDayDate(day.dayNumber);
                const isSelected = selectedDay?.dayNumber === day.dayNumber;

                const bgClass = getStatusColor(day, date, isSelected);
                const borderClass = getBorderClass(day, date, isSelected);

                const completedCount = day.tasks.filter(t => t.isCompleted).length;
                const totalTasks = day.tasks.length;

                // Calculate time
                const sessions = day.sessions || [];
                const totalTimeMs = sessions.reduce((acc, s) => acc + ((s.end || Date.now()) - s.start), 0);
                const showTime = totalTimeMs > 60000; // Only show if > 1 min

                return (
                <button
                    key={day.dayNumber}
                    onClick={() => onSelectDay(day)}
                    className={`
                    relative flex flex-col items-start p-3 rounded-xl text-left transition-all duration-200
                    ${bgClass} ${borderClass}
                    `}
                >
                    <div className="flex justify-between w-full items-start mb-2">
                        <span className="text-xs font-bold uppercase opacity-60">
                            Day {day.dayNumber}
                        </span>
                        {completedCount === totalTasks && totalTasks > 0 && (
                            <Icons.CheckCircle size={16} className="text-emerald-600" />
                        )}
                        {showTime && (
                             <span className="text-[10px] font-medium bg-gray-900/10 px-1.5 py-0.5 rounded text-gray-700 flex items-center gap-0.5">
                                <Icons.Clock size={10} />
                                {formatShortDuration(totalTimeMs)}
                            </span>
                        )}
                    </div>

                    <div className="text-xs opacity-50 mb-1 font-medium">
                        {date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                    </div>

                    <h3 className="text-sm font-semibold leading-tight line-clamp-2 mb-3 w-full">
                        {day.title}
                    </h3>

                    <div className="mt-auto w-full">
                        <div className="w-full bg-gray-900/10 rounded-full h-1.5 overflow-hidden">
                            <div 
                                className={`h-full rounded-full transition-all duration-500 ${completedCount === totalTasks ? 'bg-emerald-500' : 'bg-indigo-500'}`}
                                style={{ width: `${(completedCount / totalTasks) * 100}%` }}
                            />
                        </div>
                    </div>
                </button>
                );
            })}
            </div>
        ) : (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
                <Icons.Calendar size={48} className="mb-4 opacity-20" />
                <p>No tasks scheduled for this month.</p>
            </div>
        )}
      </div>

      <div className="mt-6 pt-4 border-t border-gray-100 flex gap-4 text-xs text-gray-500 justify-end">
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 bg-emerald-50 border border-emerald-200 rounded"></div> Completed
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 bg-red-50 border border-red-200 rounded"></div> Missed
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 border-2 border-indigo-300 rounded"></div> Today
        </div>
      </div>
    </div>
  );
};

