export const QuizModal: React.FC<QuizModalProps> = ({ isOpen, onClose, contextText, title }) => {
  const [loading, setLoading] = useState(false);
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userAnswers, setUserAnswers] = useState<number[]>([]);
  const [showResults, setShowResults] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      // Reset state
      setQuestions([]);
      setCurrentIndex(0);
      setUserAnswers([]);
      setShowResults(false);
      setError(null);
      setLoading(true);

      // Generate quiz
      generateQuiz(contextText, 5)
        .then(qs => {
          if (!qs || qs.length === 0) {
            throw new Error("No questions generated.");
          }
          setQuestions(qs);
          setLoading(false);
        })
        .catch(err => {
          console.error(err);
          setError("Failed to generate quiz. Please try again.");
          setLoading(false);
        });
    }
  }, [isOpen, contextText]);

  if (!isOpen) return null;

  const handleAnswer = (optionIndex: number) => {
    const newAnswers = [...userAnswers];
    newAnswers[currentIndex] = optionIndex;
    setUserAnswers(newAnswers);
  };

  const handleNext = () => {
    if (currentIndex < questions.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setShowResults(true);
    }
  };

  const calculateScore = () => {
    let score = 0;
    questions.forEach((q, idx) => {
      if (userAnswers[idx] === q.correctAnswerIndex) score++;
    });
    return score;
  };

  // Safe access to current question
  const currentQuestion = questions[currentIndex];

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl flex flex-col max-h-[90vh] overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-gray-100 bg-indigo-600 text-white">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-500/50 rounded-lg">
                <Icons.BrainCircuit size={24} className="text-white" />
            </div>
            <div>
                <h3 className="font-bold text-lg leading-tight">Quiz: {title}</h3>
                <p className="text-indigo-200 text-xs">Test your knowledge</p>
            </div>
          </div>
          <button onClick={onClose} className="text-indigo-200 hover:text-white transition-colors">
            <Icons.X size={24} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
            {loading || questions.length === 0 ? (
                // Show loading state if loading OR if questions haven't loaded yet (preventing the crash)
                !error ? (
                    <div className="flex flex-col items-center justify-center h-64 space-y-4">
                        <div className="animate-spin h-10 w-10 border-4 border-indigo-500 border-t-transparent rounded-full"></div>
                        <p className="text-gray-500 font-medium">Generating questions based on your plan...</p>
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-64 text-center">
                        <Icons.HelpCircle size={48} className="text-red-300 mb-4" />
                        <p className="text-gray-800 font-medium mb-2">{error}</p>
                        <button onClick={onClose} className="text-indigo-600 hover:underline">Close</button>
                    </div>
                )
            ) : showResults ? (
                <div className="space-y-6">
                    <div className="text-center p-6 bg-white rounded-xl shadow-sm border border-gray-100">
                        <div className="text-gray-500 uppercase tracking-wider text-xs font-bold mb-2">Final Score</div>
                        <div className="text-5xl font-bold text-indigo-600 mb-2">
                            {calculateScore()} / {questions.length}
                        </div>
                        <p className="text-gray-600">
                            {calculateScore() === questions.length ? "Perfect! You've mastered this topic." : 
                             calculateScore() > questions.length / 2 ? "Great job! Keep learning." : "Good effort. Review the material and try again."}
                        </p>
                    </div>

                    <div className="space-y-4">
                        <h4 className="font-bold text-gray-800">Review Answers</h4>
                        {questions.map((q, idx) => {
                            const isCorrect = userAnswers[idx] === q.correctAnswerIndex;
                            return (
                                <div key={idx} className={`p-4 rounded-lg border ${isCorrect ? 'bg-emerald-50 border-emerald-200' : 'bg-red-50 border-red-200'}`}>
                                    <div className="flex gap-3">
                                        <div className={`mt-1 flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center text-white text-xs font-bold ${isCorrect ? 'bg-emerald-500' : 'bg-red-500'}`}>
                                            {idx + 1}
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900 mb-2">{q.question}</p>
                                            <p className="text-sm text-gray-600 mb-1">
                                                Your answer: <span className={isCorrect ? 'text-emerald-700 font-semibold' : 'text-red-700 font-semibold'}>{q.options[userAnswers[idx]]}</span>
                                            </p>
                                            {!isCorrect && (
                                                <p className="text-sm text-emerald-700">
                                                    Correct answer: <span className="font-semibold">{q.options[q.correctAnswerIndex]}</span>
                                                </p>
                                            )}
                                            <div className="mt-2 text-xs bg-white/50 p-2 rounded text-gray-600 border border-black/5">
                                                <span className="font-bold">Explanation:</span> {q.explanation}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ) : currentQuestion ? (
                <div className="max-w-xl mx-auto">
                    <div className="mb-6 flex justify-between items-center">
                        <span className="text-sm font-semibold text-gray-500">Question {currentIndex + 1} of {questions.length}</span>
                        <div className="w-32 h-2 bg-gray-200 rounded-full overflow-hidden">
                            <div 
                                className="h-full bg-indigo-500 transition-all duration-300" 
                                style={{ width: `${((currentIndex + 1) / questions.length) * 100}%` }} 
                            />
                        </div>
                    </div>

                    <h4 className="text-xl font-bold text-gray-900 mb-6 leading-relaxed">
                        {currentQuestion.question}
                    </h4>

                    <div className="space-y-3 mb-8">
                        {currentQuestion.options.map((option, idx) => (
                            <button
                                key={idx}
                                onClick={() => handleAnswer(idx)}
                                className={`w-full p-4 text-left rounded-xl border-2 transition-all duration-200 flex items-center justify-between group
                                    ${userAnswers[currentIndex] === idx 
                                        ? 'border-indigo-600 bg-indigo-50 text-indigo-900' 
                                        : 'border-gray-200 bg-white hover:border-indigo-300 hover:bg-gray-50'
                                    }
                                `}
                            >
                                <span className="font-medium">{option}</span>
                                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center
                                     ${userAnswers[currentIndex] === idx ? 'border-indigo-600' : 'border-gray-300 group-hover:border-indigo-400'}
                                `}>
                                    {userAnswers[currentIndex] === idx && <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full" />}
                                </div>
                            </button>
                        ))}
                    </div>

                    <div className="flex justify-end">
                        <button
                            onClick={handleNext}
                            disabled={userAnswers[currentIndex] === undefined}
                            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-lg font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 disabled:opacity-50 disabled:shadow-none transition-all"
                        >
                            {currentIndex === questions.length - 1 ? 'Finish Quiz' : 'Next Question'}
                            <Icons.ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center h-64">
                   <p className="text-gray-500">Preparing quiz...</p>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { LearningPlan, DayPlan, QuizQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
You are an expert curriculum designer and educational coach. 
Your goal is to break down complex topics into actionable, bite-sized daily learning plans.
The plans must be practical, step-by-step, and tailored to the user's time constraints.

CRITICAL INSTRUCTION: You MUST use the Google Search tool to verify every single URL you provide. 
Do not invent or hallucinate URLs. If you cannot find a specific resource via search, do not include it.
Only include resources that currently exist and are accessible.
`;

// Helper to extract JSON robustly
function extractJson(text: string): any {
  try {
    // 1. Try to find a code block
    const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (codeBlockMatch) {
      return JSON.parse(codeBlockMatch[1]);
    }

    // 2. Try parsing the raw text directly
    return JSON.parse(text);
  } catch (e) {
    // 3. Last resort: Find the first '{' and last '}'
    const firstOpen = text.indexOf('{');
    const lastClose = text.lastIndexOf('}');
    if (firstOpen !== -1 && lastClose !== -1) {
      try {
        const potentialJson = text.substring(firstOpen, lastClose + 1);
        return JSON.parse(potentialJson);
      } catch (e2) {
        // Failed
      }
    }
    console.error("Failed to parse JSON from model response", text);
    throw new Error("The model generated an invalid format. Please try again.");
  }
}

export async function generateLearningPlan(topic: string, days: number, timePerDay: string): Promise<Omit<LearningPlan, 'id' | 'startDate' | 'lastUpdated'>> {
  const prompt = `
    Create a ${days}-day learning plan for the topic: "${topic}".
    The user can spend ${timePerDay} per day.

    EXECUTION STEPS:
    1. Search Google for the best, most up-to-date tutorials, documentation, and videos for "${topic}".
    2. Select specific, high-quality URLs from the search results.
    3. Construct the JSON plan.

    Return ONLY a JSON object with the following structure:
    {
      "topic": "${topic}",
      "durationDays": ${days},
      "dailyTime": "${timePerDay}",
      "days": [
        {
          "dayNumber": 1,
          "title": "Short title for the day",
          "description": "Detailed step-by-step instructions. Use markdown.",
          "tasks": [
            {
              "text": "The actionable task text",
              "resources": [
                { "title": "Actual Page Title", "url": "https://actual-url-found-via-search", "type": "blog" | "video" | "documentation" }
              ]
            }
          ]
        }
      ]
    }

    Requirements:
    - 'tasks' must be an array of objects, NOT strings.
    - Each task MUST have 1-2 relevant 'resources' found via Google Search.
    - URLs MUST be real and verifiable. Do NOT generate placeholders like "example.com".
    - If no specific URL is found for a task, leave the resources array empty.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }], 
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = extractJson(text);

    const formattedDays: DayPlan[] = data.days.map((d: any) => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map((t: any, idx: number) => ({
        id: `task-${d.dayNumber}-${idx}`,
        // Handle both object (new format) and string (fallback)
        text: typeof t === 'string' ? t : t.text,
        isCompleted: false,
        resources: typeof t === 'object' && t.resources ? t.resources : []
      }))
    }));

    return {
      topic: data.topic,
      durationDays: data.durationDays,
      dailyTime: data.dailyTime,
      days: formattedDays
    };

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

export async function updatePlanWithChat(currentPlan: LearningPlan, userRequest: string): Promise<LearningPlan> {
  const simplifiedPlan = {
    days: currentPlan.days.map(d => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map(t => ({ text: t.text, resources: t.resources })) 
    }))
  };

  const prompt = `
    The user wants to modify their current learning plan for "${currentPlan.topic}".

    Current Plan Structure (JSON):
    ${JSON.stringify(simplifiedPlan)}

    User Request: "${userRequest}"

    Please update the plan according to the request. 

    CRITICAL: If adding new tasks or content, YOU MUST use Google Search to find relevant, real 'resources' (url, title, type).
    Do not hallucinate URLs.

    Return ONLY the valid JSON of the updated "days" array. 
    Structure: { "days": [ ... ] }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    const data = extractJson(text);

    const updatedDays: DayPlan[] = data.days.map((d: any) => ({
      dayNumber: d.dayNumber,
      title: d.title,
      description: d.description,
      tasks: d.tasks.map((t: any, idx: number) => ({
        id: `task-${d.dayNumber}-${idx}-${Date.now()}`,
        text: typeof t === 'string' ? t : t.text,
        isCompleted: false,
        resources: typeof t === 'object' && t.resources ? t.resources : []
      }))
    }));

    return {
      ...currentPlan,
      days: updatedDays,
      durationDays: updatedDays.length,
      lastUpdated: new Date().toISOString()
    };

  } catch (error) {
    console.error("Gemini Update Error:", error);
    throw error;
  }
}

export async function generateQuiz(context: string, numQuestions: number = 5): Promise<QuizQuestion[]> {
  const prompt = `
    Create a multiple-choice quiz based on the following learning material.

    Material Context:
    "${context}"

    Requirements:
    - Generate exactly ${numQuestions} questions.
    - Questions should test understanding of key concepts in the material.
    - Provide 4 options per question.
    - Indicate the correct answer index (0-3).
    - Provide a short explanation for the correct answer.

    Return ONLY a JSON array of objects with this structure:
    [
      {
        "question": "Question text here?",
        "options": ["Option A", "Option B", "Option C", "Option D"],
        "correctAnswerIndex": 0,
        "explanation": "Why this is correct."
      }
    ]
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return extractJson(text);
  } catch (error) {
    console.error("Gemini Quiz Error:", error);
    throw error;
  }
}

export interface AnalyzedPlanResult {
    original: Omit<LearningPlan, 'id' | 'startDate' | 'lastUpdated'>;
    improved: Omit<LearningPlan, 'id' | 'startDate' | 'lastUpdated'>;
    analysis: string;
}

export async function analyzeUploadedPlan(markdownContent: string): Promise<AnalyzedPlanResult> {
    const prompt = `
      You are an expert curriculum analyzer.
      A user has uploaded a learning plan in Markdown format.

      MARKDOWN CONTENT:
      """
      ${markdownContent}
      """

      YOUR TASK:
      1. **Parse**: Extract the plan into a structured JSON format. This is the "original" plan. Even if the markdown is vague, capture it faithfully.
      2. **Think & Analyze**: Identify inconsistencies, gaps in logic, unrealistic timelines, outdated information, or lack of actionable steps.
      3. **Improve**: Create an "improved" version of the plan that fixes the identified issues. 
         - Ensure it has clear, actionable steps.
         - Ensure it has valid resources (use Google Search to find real URLs).
      4. **Summarize**: Provide a concise analysis of what was wrong and what you fixed.

      OUTPUT FORMAT (JSON ONLY):
      {
        "original": {
           "topic": "Topic Name",
           "durationDays": 5,
           "dailyTime": "30 mins",
           "days": [ ... ]
        },
        "improved": {
           "topic": "Topic Name",
           "durationDays": 5,
           "dailyTime": "30 mins",
           "days": [ ... ] 
        },
        "analysis": "Bulleted summary of issues found and improvements made."
      }

      NOTE: 
      - The 'days' array structure must match this schema: { dayNumber: number, title: string, description: string, tasks: [{ text: string, resources: [{ title: string, url: string, type: string }] }] }
      - Use 'thinkingConfig' to reason about the plan quality before generating the output.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                thinkingConfig: { thinkingBudget: 4096 },
                tools: [{ googleSearch: {} }],
            }
        });

        const text = response.text;
        if (!text) throw new Error("No response from Gemini");

        const data = extractJson(text);

        // Helper to format days to ensure they match internal types
        const formatPlan = (planData: any) => {
            const days = (planData.days || []).map((d: any) => ({
                dayNumber: d.dayNumber,
                title: d.title || `Day ${d.dayNumber}`,
                description: d.description || "",
                tasks: (d.tasks || []).map((t: any, idx: number) => ({
                    id: `task-${d.dayNumber}-${idx}`,
                    text: typeof t === 'string' ? t : t.text,
                    isCompleted: false,
                    resources: typeof t === 'object' && t.resources ? t.resources : []
                }))
            }));

            return {
                topic: planData.topic || "Imported Plan",
                durationDays: planData.durationDays || days.length,
                dailyTime: planData.dailyTime || "Flexible",
                days
            };
        };

        return {
            original: formatPlan(data.original),
            improved: formatPlan(data.improved),
            analysis: data.analysis
        };

    } catch (error) {
        console.error("Gemini Analysis Error:", error);
        throw error;
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { Icons } from './Icons';
import { generateLearningPlan, updatePlanWithChat, analyzeUploadedPlan, AnalyzedPlanResult } from '../services/geminiService';
import { LearningPlan, DayPlan } from '../types';
import { v4 as uuidv4 } from 'uuid';

interface PlanWizardProps {
  onPlanCreated: (plan: LearningPlan) => void;
  onCancel: () => void;
}

export const PlanWizard: React.FC<PlanWizardProps> = ({ onPlanCreated, onCancel }) => {
  // Tabs
  const [activeTab, setActiveTab] = useState<'create' | 'import'>('create');

  // Form State (Create)
  const [topic, setTopic] = useState('');
  const [days, setDays] = useState(7);
  const [timePerDay, setTimePerDay] = useState('30 mins');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Import State
  const [importFile, setImportFile] = useState<File | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalyzedPlanResult | null>(null);

  // Review & Refine State
  const [generatedPlan, setGeneratedPlan] = useState<LearningPlan | null>(null);
  const [refineInput, setRefineInput] = useState('');
  const [isRefining, setIsRefining] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Ref for file input
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Scroll to bottom of list when plan updates
  useEffect(() => {
    if (generatedPlan && scrollRef.current) {
        scrollRef.current.scrollTop = 0;
    }
  }, [generatedPlan?.lastUpdated]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setIsLoading(true);
    setError(null);

    try {
      const planData = await generateLearningPlan(topic, days, timePerDay);

      const newPlan: LearningPlan = {
        ...planData,
        id: uuidv4(),
        startDate: new Date().toISOString(),
        lastUpdated: new Date().toISOString(),
      };

      setGeneratedPlan(newPlan);
    } catch (err: any) {
      setError(err.message || "Failed to generate plan. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleRefine = async () => {
    if (!refineInput.trim() || !generatedPlan) return;

    setIsRefining(true);
    setError(null);
    const originalPlan = generatedPlan;

    try {
        // Optimistic UI updates or loading states happen here
        const updated = await updatePlanWithChat(generatedPlan, refineInput);
        setGeneratedPlan(updated);
        setRefineInput('');
    } catch (err: any) {
        setError("Failed to update plan. Please try again.");
        setGeneratedPlan(originalPlan);
    } finally {
        setIsRefining(false);
    }
  };

  const handleConfirm = () => {
      if (generatedPlan) {
          onPlanCreated(generatedPlan);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setImportFile(e.target.files[0]);
      setError(null);
    }
  };

  const handleImport = async () => {
    if (!importFile) return;

    setIsLoading(true);
    setError(null);

    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      try {
        const result = await analyzeUploadedPlan(text);
        setAnalysisResult(result);
      } catch (err: any) {
        setError(err.message || "Failed to analyze plan. Please check the file format.");
      } finally {
        setIsLoading(false);
      }
    };
    reader.readAsText(importFile);
  };

  const applyAnalyzedPlan = (useImproved: boolean) => {
      if (!analysisResult) return;

      const basePlan = useImproved ? analysisResult.improved : analysisResult.original;

      const newPlan: LearningPlan = {
          ...basePlan,
          id: uuidv4(),
          startDate: new Date().toISOString(),
          lastUpdated: new Date().toISOString()
      };

      setGeneratedPlan(newPlan);
      // Clear analysis result so we go to preview mode
      setAnalysisResult(null); 
  };

  // --------------------------------------------------------------------------
  // RENDER: PREVIEW MODE (Shared)
  // --------------------------------------------------------------------------
  if (generatedPlan) {
    return (
        <div className="w-full max-w-4xl bg-white rounded-xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh] animate-in fade-in zoom-in-95 duration-300">
            {/* Header */}
            <div className="p-6 border-b border-gray-100 flex justify-between items-start bg-indigo-600 text-white">
                <div>
                    <div className="flex items-center gap-2 mb-1 opacity-90 text-sm font-medium uppercase tracking-wider">
                        <Icons.Sparkles size={14} /> Plan Preview
                    </div>
                    <h2 className="text-2xl font-bold">{generatedPlan.topic}</h2>
                    <div className="flex gap-4 mt-2 text-indigo-100 text-sm">
                        <span className="flex items-center gap-1"><Icons.Calendar size={14} /> {generatedPlan.durationDays} Days</span>
                        <span className="flex items-center gap-1"><Icons.Clock size={14} /> {generatedPlan.dailyTime}/day</span>
                    </div>
                </div>
                <button onClick={() => setGeneratedPlan(null)} className="text-indigo-200 hover:text-white transition-colors bg-indigo-700/50 p-2 rounded-lg">
                    <Icons.X size={20} />
                </button>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                {/* Left: Plan Content List */}
                <div className="flex-1 overflow-y-auto bg-gray-50 p-6" ref={scrollRef}>
                    <h3 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                        <Icons.BookOpen size={18} className="text-indigo-600" />
                        Curriculum Overview
                    </h3>
                    <div className="space-y-4">
                        {generatedPlan.days.map((day) => (
                            <div key={day.dayNumber} className="bg-white p-4 rounded-lg border border-gray-200 shadow-sm">
                                <div className="flex justify-between items-start mb-2">
                                    <span className="text-xs font-bold text-indigo-600 uppercase tracking-wide">Day {day.dayNumber}</span>
                                </div>
                                <h4 className="font-bold text-gray-800 mb-2">{day.title}</h4>
                                <p className="text-sm text-gray-600 line-clamp-3 mb-3">{day.description}</p>
                                <div className="flex gap-2 flex-wrap">
                                    {day.tasks.slice(0, 2).map((task, i) => (
                                        <span key={i} className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-md border border-gray-200 truncate max-w-[200px]">
                                            {task.text}
                                        </span>
                                    ))}
                                    {day.tasks.length > 2 && (
                                        <span className="text-xs text-gray-400 px-1 py-1">+{day.tasks.length - 2} more</span>
                                    )}
