        className="flex items-start gap-3 p-3 cursor-pointer hover:bg-gray-50/50"
        onClick={() => hasResources ? setIsExpanded(!isExpanded) : onToggle(task.id)}
      >
         <div 
          onClick={(e) => { e.stopPropagation(); onToggle(task.id); }}
          className="mt-1"
        >
          <div className={`
             w-4 h-4 rounded border flex items-center justify-center transition-colors
             ${task.isCompleted ? 'bg-emerald-500 border-emerald-500' : 'border-gray-300 bg-white hover:border-indigo-400'}
          `}>
             {task.isCompleted && <Icons.CheckCircle size={12} className="text-white" />}
          </div>
        </div>

        <div className="flex-1">
          <span className={`text-sm ${task.isCompleted ? 'text-emerald-800 line-through opacity-70' : 'text-gray-700'}`}>
              {task.text}
          </span>
        </div>

        {hasResources && (
          <button 
            onClick={(e) => { e.stopPropagation(); setIsExpanded(!isExpanded); }}
            className="text-gray-400 hover:text-indigo-600 transition-colors"
          >
            {isExpanded ? <Icons.ChevronUp size={16} /> : <Icons.ChevronDown size={16} />}
          </button>
        )}
      </div>

      {isExpanded && hasResources && (
        <div className="bg-gray-50/80 px-4 pb-3 pt-0 border-t border-gray-100/50">
          <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2 mt-2 flex items-center gap-1">
             <Icons.BookOpen size={10} /> Suggested Resources
          </div>
          <div className="space-y-2">
            {task.resources?.map((res, idx) => (
              <a 
                key={idx}
                href={res.url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-2 p-2 rounded-md bg-white border border-gray-200 hover:border-indigo-300 hover:shadow-sm transition-all group"
              >
                <div className="text-indigo-500">
                  {res.type === 'video' ? <Icons.Video size={14} /> : 
                   res.type === 'documentation' ? <Icons.FileText size={14} /> : 
                   <Icons.ExternalLink size={14} />}
                </div>
                <span className="text-xs text-gray-700 font-medium truncate flex-1 group-hover:text-indigo-700">
                  {res.title}
                </span>
                <Icons.ExternalLink size={10} className="text-gray-300 group-hover:text-indigo-400" />
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const PlanDetail: React.FC<PlanDetailProps> = ({ 
  day, 
  plan, 
  isVisible, 
  onClose, 
  onToggleTask,
  onUpdateNotes,
  onToggleSession,
  onSelectDay
}) => {
  const [notesInput, setNotesInput] = useState('');
  const [elapsed, setElapsed] = useState(0);
  const [isQuizOpen, setIsQuizOpen] = useState(false);

  // Reset notes when day changes
  useEffect(() => {
      if (day) {
          setNotesInput(day.notes || '');
      }
  }, [day]);

  // Timer logic
  useEffect(() => {
    let interval: any;
    if (day && isVisible) {
        const calculateTotal = () => {
             const sessions = day.sessions || [];
             let total = 0;
             let running = false;
             const now = Date.now();

             sessions.forEach(s => {
                 if (s.end) {
                     total += s.end - s.start;
                 } else {
                     total += now - s.start;
                     running = true;
                 }
             });
             return { total, running };
        };

        setElapsed(calculateTotal().total);

        interval = setInterval(() => {
            const { total } = calculateTotal();
            setElapsed(total);
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [day, isVisible]);

  if (!isVisible) return null;

  const handleNotesBlur = () => {
      if (day && notesInput !== day.notes) {
          onUpdateNotes(day.dayNumber, notesInput);
      }
  };

  const handlePrevDay = () => {
    if (!day) return;
    const prevDay = plan.days.find(d => d.dayNumber === day.dayNumber - 1);
    if (prevDay) onSelectDay(prevDay);
  };

  const handleNextDay = () => {
    if (!day) return;
    const nextDay = plan.days.find(d => d.dayNumber === day.dayNumber + 1);
    if (nextDay) onSelectDay(nextDay);
  };

  const isSessionRunning = day?.sessions && day.sessions.length > 0 && day.sessions[day.sessions.length - 1].end === null;

  const formatTime = (ms: number) => {
      const seconds = Math.floor((ms / 1000) % 60);
      const minutes = Math.floor((ms / (1000 * 60)) % 60);
      const hours = Math.floor((ms / (1000 * 60 * 60)));
      return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <>
        <div className={`
        fixed inset-y-0 right-0 w-full sm:w-96 bg-white shadow-2xl transform transition-transform duration-300 ease-in-out z-30 flex flex-col
        ${isVisible ? 'translate-x-0' : 'translate-x-full'}
        `}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-100 bg-white">
            <h2 className="text-lg font-bold text-gray-800">Daily Plan Details</h2>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
            <Icons.X size={20} />
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto bg-gray-50">

            {day ? (
                <div className="p-6">
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center bg-white border border-gray-200 rounded-lg p-1 shadow-sm">
                            <button
                                onClick={handlePrevDay}
                                disabled={day.dayNumber <= 1}
                                className="p-1.5 rounded-md text-gray-500 hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                                title="Previous Day"
                            >
                                <Icons.ChevronLeft size={16} />
                            </button>
                            <span className="px-3 text-sm font-bold text-indigo-700 min-w-[60px] text-center uppercase tracking-wide">
                                Day {day.dayNumber}
                            </span>
                            <button
                                onClick={handleNextDay}
                                disabled={day.dayNumber >= plan.days.length}
                                className="p-1.5 rounded-md text-gray-500 hover:bg-gray-100 disabled:opacity-30 disabled:hover:bg-transparent transition-all"
                                title="Next Day"
                            >
                                <Icons.ChevronRight size={16} />
                            </button>
                        </div>
                        <button
                            onClick={() => setIsQuizOpen(true)}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-indigo-50 text-indigo-700 text-xs font-semibold hover:bg-indigo-100 transition-colors"
                        >
                            <Icons.BrainCircuit size={14} />
                            Take Quiz
                        </button>
                    </div>

                    <h2 className="text-2xl font-bold text-gray-900 mb-6">{day.title}</h2>

                    {/* Timer Section */}
                    <div className="bg-indigo-900 rounded-xl p-5 text-white mb-8 shadow-lg relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-4 opacity-10">
                            <Icons.Timer size={80} />
                        </div>
                        <div className="relative z-10">
                            <div className="text-indigo-200 text-xs font-semibold uppercase tracking-wider mb-1">Time Spent Today</div>
                            <div className="text-4xl font-mono font-bold mb-4 tracking-wider">
                                {formatTime(elapsed)}
                            </div>
                            <button 
                                onClick={() => onToggleSession(day.dayNumber)}
                                className={`
                                    w-full flex items-center justify-center gap-2 py-2.5 rounded-lg font-bold text-sm transition-all
                                    ${isSessionRunning 
                                        ? 'bg-red-500 hover:bg-red-600 text-white shadow-md' 
                                        : 'bg-emerald-500 hover:bg-emerald-600 text-white shadow-md'}
                                `}
                            >
                                {isSessionRunning ? (
                                    <>
                                        <Icons.Square size={16} fill="currentColor" /> Stop Session
                                    </>
                                ) : (
                                    <>
                                        <Icons.Play size={16} fill="currentColor" /> Start Learning
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {/* Tasks Section */}
                    <div className="space-y-3 mb-8">
                        <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                            <Icons.CheckCircle size={18} className="text-indigo-600" />
                            Tasks Checklist
                        </h3>
                        <div className="bg-gray-50 rounded-xl p-2 border border-gray-100">
                            {day.tasks.map((task) => (
                            <TaskItem 
                                key={task.id} 
                                task={task} 
                                onToggle={(id) => onToggleTask(day.dayNumber, id)} 
                            />
                            ))}
                        </div>
                    </div>

                    {/* Description Section */}
                    <div className="mb-8">
                            <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                            <Icons.BookOpen size={18} className="text-indigo-600" />
                            Step-by-Step Guide
                        </h3>
                        <div className="prose prose-sm prose-indigo max-w-none bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                            <SimpleMarkdown text={day.description} />
                        </div>
                    </div>

                    {/* Notes Section */}
                    <div className="mb-8">
                        <h3 className="font-semibold text-gray-800 flex items-center gap-2 mb-3">
                            <Icons.MessageSquare size={18} className="text-indigo-600" />
                            My Learning Notes
                        </h3>
                        <textarea
                            value={notesInput}
                            onChange={(e) => setNotesInput(e.target.value)}
                            onBlur={handleNotesBlur}
                            placeholder="Write down your key takeaways, code snippets, or ideas here..."
                            className="w-full h-32 p-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm text-gray-700 placeholder-gray-400 resize-y"
                        />
                        <p className="text-xs text-gray-400 mt-1 text-right">Saved automatically on blur</p>
                    </div>
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center h-full text-gray-400 p-8 text-center">
                    <Icons.Calendar size={48} className="mb-4 opacity-20" />
                    <p>Select a day from the calendar to view details.</p>
                </div>
            )}
        </div>
        </div>

        {/* Quiz Modal Integration for specific day */}
        {day && (
            <QuizModal 
                isOpen={isQuizOpen}
                onClose={() => setIsQuizOpen(false)}
                contextText={`Topic: ${plan.topic}\n\nDay ${day.dayNumber}: ${day.title}\n${day.description}\n\nTasks:\n${day.tasks.map(t => `- ${t.text}`).join('\n')}`}
                title={`Day ${day.dayNumber} - ${day.title}`}
            />
        )}
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { PlanWizard } from './components/PlanWizard';
import { PlanCalendar } from './components/PlanCalendar';
import { PlanDetail } from './components/PlanDetail';
import { EditPlanModal } from './components/EditPlanModal';
import { QuizModal } from './components/QuizModal';
import { Icons } from './components/Icons';
import { LearningPlan, DayPlan } from './types';

// Storage key
const STORAGE_KEY = 'skillpath_plans_v1';

// Background Images (Digital Art)
const BG_LANDING = "url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')";
const BG_PLAN = "url('https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=2574&auto=format&fit=crop')";

const App: React.FC = () => {
  const [plans, setPlans] = useState<LearningPlan[]>([]);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'create' | 'view'>('view');

  // UI State
  const [selectedDay, setSelectedDay] = useState<DayPlan | null>(null);
  const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  // Quiz State
  const [isQuizOpen, setIsQuizOpen] = useState(false);
  const [quizContext, setQuizContext] = useState('');
  const [quizTitle, setQuizTitle] = useState('');

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsedPlans = JSON.parse(saved);
        setPlans(parsedPlans);
        if (parsedPlans.length > 0) {
          setActivePlanId(parsedPlans[0].id);
        } else {
          setViewMode('create');
        }
      } catch (e) {
        console.error("Failed to parse saved plans");
      }
    } else {
        setViewMode('create');
    }
  }, []);

  // Save to local storage whenever plans change
  useEffect(() => {
    if (plans.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(plans));
    }
  }, [plans]);

  // Select today's day automatically when opening a plan
  useEffect(() => {
    if (activePlanId && plans.length > 0) {
      const plan = plans.find(p => p.id === activePlanId);
      if (plan) {
        const today = new Date();
        today.setHours(0,0,0,0);
        const startDate = new Date(plan.startDate);

        // Calculate diff in days
        const diffTime = Math.abs(today.getTime() - startDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // If today is within the plan range, select it
        if (today >= startDate && diffDays < plan.days.length) {
            // Find the day with index matches today relative to start
            const targetDay = plan.days.find(d => d.dayNumber === diffDays + 1);
            if (targetDay) {
                setSelectedDay(targetDay);
            }
        }
      }
    }
  }, [activePlanId, plans]);

  const handleCreatePlan = (newPlan: LearningPlan) => {
    setPlans(prev => [newPlan, ...prev]);
    setActivePlanId(newPlan.id);
    setViewMode('view');
    // Select first day by default for new plan
    setSelectedDay(newPlan.days[0]);
    setIsSidePanelOpen(true);
  };

  const handleDeletePlan = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Are you sure you want to delete this plan?")) {
      const newPlans = plans.filter(p => p.id !== id);
      setPlans(newPlans);
      if (activePlanId === id) {
        setActivePlanId(newPlans.length > 0 ? newPlans[0].id : null);
        if (newPlans.length === 0) setViewMode('create');
      }
    }
  };

  const handleToggleTask = (dayNumber: number, taskId: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return {
            ...day,
            tasks: day.tasks.map(task => 
              task.id === taskId ? { ...task, isCompleted: !task.isCompleted } : task
            )
          };
        })
      };
    }));

    // Update selected day reference to trigger re-renders in side panel
    if (selectedDay && selectedDay.dayNumber === dayNumber) {
        // Force re-render not needed as props will update
    }
  };

  const handleUpdateNotes = (dayNumber: number, notes: string) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;
          return { ...day, notes };
        })
      };
    }));
  };

  const handleSessionToggle = (dayNumber: number) => {
    if (!activePlanId) return;

    setPlans(prevPlans => prevPlans.map(plan => {
      if (plan.id !== activePlanId) return plan;

      return {
        ...plan,
        days: plan.days.map(day => {
          if (day.dayNumber !== dayNumber) return day;

          const sessions = day.sessions || [];
          const lastSession = sessions.length > 0 ? sessions[sessions.length - 1] : null;
          const isRunning = lastSession && lastSession.end === null;

          let newSessions;
          if (isRunning) {
            // Stop session
            newSessions = [...sessions];
            newSessions[sessions.length - 1] = { ...lastSession, end: Date.now() };
          } else {
            // Start session
            newSessions = [...sessions, { start: Date.now(), end: null }];
          }

          return { ...day, sessions: newSessions };
        })
      };
    }));
  };

  // Need to ensure SelectedDay stays in sync with plans state
  const activePlan = plans.find(p => p.id === activePlanId);
  const currentSelectedDay = activePlan?.days.find(d => d.dayNumber === selectedDay?.dayNumber) || null;

  const handleUpdatePlan = (updatedPlan: LearningPlan) => {
      setPlans(prev => prev.map(p => p.id === updatedPlan.id ? updatedPlan : p));
  };

  const handleStartPlanQuiz = () => {
    if (!activePlan) return;

    // Construct context for the entire plan
    const context = `
      Topic: ${activePlan.topic}

      ${activePlan.days.map(day => `Day ${day.dayNumber}: ${day.title}\n${day.description}`).join('\n\n')}
    `;

    setQuizTitle(`Full Plan - ${activePlan.topic}`);
    setQuizContext(context);
    setIsQuizOpen(true);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row h-screen overflow-hidden font-sans">

      {/* Sidebar Navigation */}
      <div 
        className={`bg-white border-r border-gray-200 flex flex-col h-auto md:h-full z-20 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'md:w-20' : 'md:w-64'} w-full`}
      >
        <div className={`p-4 border-b border-gray-100 flex items-center ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}`}>
            <div className="flex items-center gap-2 overflow-hidden">
                <div className="bg-indigo-600 p-1.5 rounded-lg flex-shrink-0">
                    <Icons.BookOpen className="text-white" size={20} />
                </div>
                <h1 className={`font-bold text-xl text-gray-800 tracking-tight whitespace-nowrap transition-opacity duration-200 ${isSidebarCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
                    SkillPath
                </h1>
            </div>
            <button 
                onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
                className={`text-gray-400 hover:text-indigo-600 p-1 rounded-md hover:bg-gray-100 transition-colors hidden md:block`}
            >
                <Icons.PanelLeft size={18} />
            </button>
        </div>

        <div className="p-3 flex-1 overflow-y-auto">
          {!isSidebarCollapsed && (
             <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 px-2">Your Plans</div>
          )}

          <div className="space-y-2">
            {plans.map(plan => (
              <div 
                key={plan.id}
                onClick={() => {
                  setActivePlanId(plan.id);
                  setViewMode('view');
                }}
                className={`
                    group flex items-center p-2.5 rounded-lg cursor-pointer transition-all
                    ${activePlanId === plan.id && viewMode === 'view' ? 'bg-indigo-50 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}
                    ${isSidebarCollapsed ? 'justify-center' : 'justify-between'}
                `}
                title={isSidebarCollapsed ? plan.topic : ''}
              >
                <div className="flex items-center gap-3 overflow-hidden">
                  <div className={`w-2 h-2 rounded-full flex-shrink-0 ${activePlanId === plan.id ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                  <span className={`font-medium text-sm truncate transition-all duration-200 ${isSidebarCollapsed ? 'w-0 opacity-0 hidden' : 'w-auto opacity-100'}`}>
                    {plan.topic}
                  </span>
                </div>
                {!isSidebarCollapsed && (
                    <button 
                        onClick={(e) => handleDeletePlan(plan.id, e)}
                        className="opacity-0 group-hover:opacity-100 text-gray-400 hover:text-red-500 transition-opacity p-1"
                    >
                        <Icons.Trash2 size={14} />
                    </button>
                )}
              </div>
            ))}
          </div>

          <button
            onClick={() => setViewMode('create')}
            className={`
                w-full mt-4 flex items-center gap-2 p-3 rounded-lg text-sm font-medium border border-dashed border-gray-300 text-gray-500 hover:border-indigo-400 hover:text-indigo-600 transition-all 
                ${viewMode === 'create' ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : ''}
                ${isSidebarCollapsed ? 'justify-center px-0' : ''}
            `}
            title={isSidebarCollapsed ? "Create New Plan" : ""}
          >
            <Icons.Plus size={isSidebarCollapsed ? 20 : 16} />
            {!isSidebarCollapsed && <span>New Plan</span>}
          </button>
        </div>
      </div>

      {/* Main Content Area with Background */}
      <div 
        className="flex-1 flex flex-col h-full relative overflow-hidden bg-gray-50 transition-all duration-500"
        style={{ 
            backgroundImage: viewMode === 'create' ? BG_LANDING : BG_PLAN,
            backgroundSize: 'cover',
            backgroundPosition: 'center'
        }}
      >
        {/* Overlay for better readability */}
        <div className="absolute inset-0 bg-white/30 backdrop-blur-[2px] z-0 pointer-events-none"></div>

        {viewMode === 'create' ? (
          <div className="flex-1 overflow-y-auto p-4 md:p-8 flex items-center justify-center relative z-10">
            <PlanWizard 
                onPlanCreated={handleCreatePlan} 
                onCancel={() => plans.length > 0 ? setViewMode('view') : null}
            />
          </div>
        ) : (
          activePlan && (
            <div className="flex-1 flex flex-col h-full overflow-hidden p-4 md:p-6 relative z-10">
              {/* Toolbar */}
              <div className="flex justify-between items-center mb-4 bg-white/80 backdrop-blur-md p-3 rounded-xl border border-white/50 shadow-sm">
                  <h2 className="text-lg font-bold text-gray-800 hidden md:block px-2">Learning Progress</h2>
                  <div className="flex gap-3 ml-auto md:ml-0">
                    <button 
                        onClick={handleStartPlanQuiz}
                        className="flex items-center gap-2 px-3 py-2 bg-white text-indigo-600 border border-indigo-200 rounded-lg hover:bg-indigo-50 text-sm font-medium transition-all shadow-sm"
                    >
                        <Icons.BrainCircuit size={16} />
                        Generate Quiz
                    </button>
                    <button 
                        onClick={() => setIsEditModalOpen(true)}
                        className="flex items-center gap-2 px-3 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-all shadow-sm shadow-indigo-200"
                    >
                        <Icons.Sparkles size={16} />
                        Edit Plan
                    </button>
                    <button 
                        onClick={() => setIsSidePanelOpen(!isSidePanelOpen)}
                        className={`md:hidden p-2 rounded-lg border ${isSidePanelOpen ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600'}`}
                    >
                        <Icons.Layout size={20} />
                    </button>
                  </div>
              </div>

              {/* Calendar Grid - Wrapped in transculent bg handled by component or here */}
              <div className="flex-1 overflow-hidden rounded-xl shadow-lg border border-white/50 bg-white/90 backdrop-blur-sm">
                <PlanCalendar 
                    plan={activePlan} 
                    selectedDay={currentSelectedDay}
                    onSelectDay={(day) => {
                        setSelectedDay(day);
                        setIsSidePanelOpen(true);
                    }}
                />
              </div>

              {/* Side Panel */}
              <PlanDetail 
                day={currentSelectedDay}
                plan={activePlan}
                isVisible={isSidePanelOpen}
                onClose={() => setIsSidePanelOpen(false)}
                onToggleTask={handleToggleTask}
                onUpdateNotes={handleUpdateNotes}
                onToggleSession={handleSessionToggle}
                onSelectDay={setSelectedDay}
              />

              {/* Edit Plan Modal */}
              <EditPlanModal 
                plan={activePlan}
                isOpen={isEditModalOpen}
                onClose={() => setIsEditModalOpen(false)}
                onPlanUpdate={handleUpdatePlan}
              />

              {/* Quiz Modal */}
              <QuizModal
                isOpen={isQuizOpen}
                onClose={() => setIsQuizOpen(false)}
                contextText={quizContext}
                title={quizTitle}
              />
            </div>
          )
        )}
      </div>
    </div>
  );
};

